(() => {
'use strict';
const STORAGE='unityield-pms-v1'; // Keep legacy key to preserve existing user records after rebranding.
const $=s=>document.querySelector(s);
const el=(id)=>document.getElementById(id);
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id_'+Date.now()+'_'+Math.random().toString(36).slice(2);
const today=()=>new Date().toLocaleDateString('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}); // locale-independent local date below
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const monthNow=()=>localToday().slice(0,7);
const plusMonths=(ym,delta)=>{const [y,m]=ym.split('-').map(Number);const d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;};
const plusDays=(iso,days)=>{const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const fmtMonth=ym=>new Date(`${ym}-01T12:00:00`).toLocaleDateString('en-US',{month:'long',year:'numeric'});
const fmtDate=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';
const fmtShortDate=s=>s?new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'}):'—';
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:db?.settings?.currency||'USD',maximumFractionDigits:0}).format(Number.isFinite(+n)?+n:0);
const preciseMoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:db?.settings?.currency||'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(Number.isFinite(+n)?+n:0);
const percent=n=>`${(Number.isFinite(+n)?+n:0).toFixed(1)}%`;
const short=s=>String(s??'').trim();
function empty(){return {version:1,settings:{name:'My Property Portfolio',currency:'USD',demo:false},properties:[],units:[],tenants:[],leases:[],payments:[],expenses:[],maintenance:[],tasks:[],activity:[],deals:[],communications:[]};}
function readDb(){try{const raw=localStorage.getItem(STORAGE);if(!raw)return empty();const data=JSON.parse(raw);if(!validDb(data))return empty();return data.settings.demo===true?empty():normalizeDb(data);}catch(e){return empty();}}
function normalizeDb(x){if(!Array.isArray(x.expenses))x.expenses=[];if(!Array.isArray(x.deals))x.deals=[];if(!Array.isArray(x.communications))x.communications=[];return x;}
function validDb(x){return !!(x&&x.version===1&&x.settings&&typeof x.settings==='object'&&['properties','units','tenants','leases','payments','maintenance','tasks','activity'].every(k=>Array.isArray(x[k])));}
function blankAnalyzer(){return {price:'',units:'',down:'',loanType:'',rate:'',years:'',closingPct:'',repairs:'',taxPct:'',insurance:'',hoa:'',miPct:'',financeUpfront:false,rent:'',occupied:'',vacancy:'',maintenance:'',capex:'',management:'',utilities:'',other:'',targetRoi:'',targetCash:''};}
const ESTIMATE_DEFAULTS={loanType:'conventional',years:30,closingPct:3,repairs:0,taxPct:1.5,insurance:225,hoa:0,miPct:1,rent:0,vacancy:5,maintenance:10,capex:5,management:0,utilities:0,other:0,targetRoi:12,targetCash:100};
function effectiveDeal(raw){const a={...ESTIMATE_DEFAULTS,...raw};for(const [k,v] of Object.entries(ESTIMATE_DEFAULTS))if(raw[k]===''||raw[k]===null||raw[k]===undefined)a[k]=v;
 if(!raw.loanType)a.loanType='conventional';a.down=raw.down??'';a.rate=raw.rate??'';if(raw.miPct==='')a.miPct=a.loanType==='fha'?.55:1;
 a.occupied=raw.occupied===''||raw.occupied===null||raw.occupied===undefined?Number(a.units):Number(raw.occupied);
 a.financeUpfront=!!raw.financeUpfront;return a;}
function dealReady(a){return Number(a.price)>0&&Number.isInteger(Number(a.units))&&Number(a.units)>=1&&Number(a.units)<=500&&Number(a.rent)>=0&&a.rent!==''&&a.down!==''&&a.down!==null&&a.down!==undefined&&Number.isFinite(Number(a.down))&&Number(a.down)>=0&&Number(a.down)<=100&&a.rate!==''&&a.rate!==null&&a.rate!==undefined&&Number.isFinite(Number(a.rate))&&Number(a.rate)>=0&&Number(a.rate)<=40;}

let db=readDb();let ui={analyzerMode:'quick',selectedDeals:[],editingDealId:null,route:location.hash.slice(1).split('/')[0]||'overview',moreTab:location.hash.split('/')[1]||'',property:'all',search:'',month:monthNow(),calendarMonth:monthNow(),rentFilter:'all',maintenanceFilter:'all',unitView:'board',analyzer:blankAnalyzer(),modal:null,report:{type:'expenses',property:'all',from:'',to:'',orientation:'landscape',columnsByType:{},includeTotals:true,title:''}};
const ROUTES=['overview','properties','units','tenants','leases','rent','expenses','maintenance','tasks','calendar','reports','more'];
if(!ROUTES.includes(ui.route))ui.route='overview';if(ui.route==='more'&&ui.moreTab==='reports'){ui.route='reports';ui.moreTab='';}
function save(description='',detail='',type='info') {if(description){db.activity.unshift({id:id(),date:new Date().toISOString(),description,detail,type});db.activity=db.activity.slice(0,150);}db.settings.demo=false;try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch(e){toast('Browser storage full. Export a backup.','error');}render();window.CloudSync?.scheduleSave(db);}
function record(description,detail='',type='info'){save(description,detail,type);}
function find(collection,idValue){return db[collection].find(x=>x.id===idValue);}
function propName(propId){return find('properties',propId)?.name||'Unknown property';}
function unitName(unitId){if(!unitId)return 'Common area';const u=find('units',unitId);return u?`${u.label} · ${propName(u.propertyId)}`:'Unknown unit';}
function tenantName(tenantId){return find('tenants',tenantId)?.name||'Unknown resident';}
function onlyProp(items,getProp){return ui.property==='all'?items:items.filter(item=>getProp(item)===ui.property);}
function getLeaseUnit(l){return find('units',l.unitId);}
function isOverlap(l,start,end){return l.start<=end&&l.end>=start;}
function activeLease(unitId,at=localToday()){return db.leases.find(l=>l.unitId===unitId&&l.status==='active'&&l.start<=at&&l.end>=at);}
function unitState(u){if(u.status==='offline')return 'Offline';const l=activeLease(u.id);if(l)return 'Occupied';if(db.leases.some(x=>x.unitId===u.id&&x.status==='active'&&x.start>localToday()))return 'Reserved';return 'Vacant';}
function rentalUnits(){return onlyProp(db.units,x=>x.propertyId).filter(x=>x.status!=='offline');}
function scopedLeases(){return onlyProp(db.leases,x=>getLeaseUnit(x)?.propertyId);}
function monthLeases(ym){const end=plusMonths(ym,1)+'-01',last=plusDays(end,-1);return scopedLeases().filter(l=>l.start<=last&&l.end>=ym+'-01');}
function paidFor(leaseId,ym){return db.payments.filter(p=>p.leaseId===leaseId&&p.month===ym).reduce((s,p)=>s+(+p.amount||0),0);}
function ledger(ym){return monthLeases(ym).map(l=>{const paid=paidFor(l.id,ym),rent=+l.rent||0;return {...l,paid,due:rent,remaining:Math.max(0,rent-paid),overpaid:Math.max(0,paid-rent)};});}
function financialSummary(ym){const rows=ledger(ym);return {due:rows.reduce((s,l)=>s+l.due,0),paid:rows.reduce((s,l)=>s+l.paid,0),balance:rows.reduce((s,l)=>s+l.remaining,0),rows};}
function icon(name){const paths={
'layout-dashboard':'<rect x="3" y="3" width="7" height="9" rx="1"/><rect x="14" y="3" width="7" height="5" rx="1"/><rect x="14" y="12" width="7" height="9" rx="1"/><rect x="3" y="16" width="7" height="5" rx="1"/>',
'building-2':'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M9 22v-4h6v4M8 6h.01M12 6h.01M16 6h.01M8 10h.01M12 10h.01M16 10h.01M8 14h.01M12 14h.01M16 14h.01"/>',
'door-open':'<path d="M3 21h18M5 21V4l12-2v19M17 21V7h4v14M12 12h.01"/>',
'users-round':'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3.1a4 4 0 0 1 0 7.8M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/>',
'file-signature':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h5M8 17h2m3 1 5-5 2 2-5 5-3 1z"/>',
'wallet':'<rect x="2" y="6" width="20" height="15" rx="2"/><path d="M2 10h20M18 15h.01M6 6V3h12"/>',
'wrench':'<path d="M14.8 6.2a6 6 0 0 0-7.5 7.5L2.5 18.5a2 2 0 0 0 3 3l4.8-4.8a6 6 0 0 0 7.5-7.5l-4 4-3-3z"/>',
'check-check':'<path d="m18 6-7 7-3-3M22 10l-8 8-3-3M2 12l4 4"/>',
'calendar-days':'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18M8 14h.01M12 14h.01M16 14h.01"/>',
'ellipsis':'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>',
'search':'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
'circle-help':'<circle cx="12" cy="12" r="10"/><path d="M9 9a3 3 0 0 1 6 1c0 2-3 2-3 4M12 17h.01"/>',
'plus':'<path d="M12 5v14M5 12h14"/>',
'chevron-left':'<path d="m15 18-6-6 6-6"/>',
'chevron-right':'<path d="m9 18 6-6-6-6"/>',
'x':'<path d="M18 6 6 18M6 6l12 12"/>',
'house':'<path d="m3 10 9-7 9 7v11H3V10ZM9 21v-8h6v8"/>',
'circle-dollar-sign':'<circle cx="12" cy="12" r="10"/><path d="M12 6v12M16 9c-2-3-8-2-8 1 0 4 8 2 8 6-1 3-6 4-8 1"/>',
'chart-no-axes-combined':'<path d="M3 3v18h18M7 16l5-6 4 3 5-7"/>',
'activity':'<path d="M3 12h4l3-7 4 14 3-7h4"/>',
'alert-circle':'<circle cx="12" cy="12" r="10"/><path d="M12 7v6M12 17h.01"/>',
'clipboard-list':'<rect x="6" y="4" width="12" height="18" rx="2"/><path d="M9 4a3 3 0 0 1 6 0M9 11h6M9 15h6"/>',
'cloud':'<path d="M20 16.6A4.4 4.4 0 0 0 18 8a6 6 0 0 0-11-1 4.7 4.7 0 0 0 1 9.6h12Z"/>',
'settings':'<circle cx="12" cy="12" r="3"/><path d="M19 12a7 7 0 0 0-.1-1l2-1.5-2-3.5-2.3 1a7 7 0 0 0-1.8-1L14.5 3h-5L9 6a7 7 0 0 0-2 1L4.7 6 2.5 9.5l2 1.5a7 7 0 0 0 0 2l-2 1.5L4.7 18l2.3-1a7 7 0 0 0 2 1l.5 3h5l.5-3a7 7 0 0 0 1.8-1l2.3 1 2-3.5-2-1.5c.1-.3.1-.7.1-1Z"/>',
'download':'<path d="M12 3v13m-5-5 5 5 5-5M4 18v3h16v-3"/>',
'upload':'<path d="M12 18V5m-5 5 5-5 5 5M4 18v3h16v-3"/>',
'arrow-up-right':'<path d="M6 18 18 6M8 6h10v10"/>',
'arrow-down-right':'<path d="M6 6 18 18M8 18h10V8"/>',
'check':'<path d="m4 12 5 5L20 6"/>',
'file-text':'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h8"/>',
'shield-check':'<path d="m12 2 9 4v6c0 6-4 9-9 10-5-1-9-4-9-10V6Z"/><path d="m8 12 3 3 5-6"/>',
'info':'<circle cx="12" cy="12" r="10"/><path d="M12 11v6M12 7h.01"/>',
'filter':'<path d="M4 7h16M7 12h10M10 17h4"/>',
'lock':'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>'};
 return `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths['info']}</svg>`;}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=icon(n.dataset.icon));}
const badge=(label,kind='neutral')=>`<span class="badge ${kind}">${safe(label)}</span>`;
function statusBadge(label){const s=String(label||'').toLowerCase();return badge(label, ['paid','occupied','complete','completed','active','done','current'].includes(s)?'success':['overdue','urgent','offline','terminated'].includes(s)?'danger':['partial','open','reserved','expiring','high','in progress'].includes(s)?'warning':['vacant','future','upcoming'].includes(s)?'info':'neutral');}
function statCard(label,value,foot,ico){return `<div class="stat-card"><div class="stat-top"><span class="stat-label">${safe(label)}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${safe(foot)}</div></div>`;}
function pageHeader(eyebrow,title,subtitle,actions=''){return `<div class="page-intro"><div><div class="eyebrow">${safe(eyebrow)}</div><h1 class="page-title">${safe(title)}</h1><p class="page-subtitle">${safe(subtitle)}</p></div>${actions?`<div class="intro-actions">${actions}</div>`:''}</div>`;}
function emptyView(title,subtitle,action='',actionName=''){return `<div class="empty"><div class="empty-icon">${icon('building-2')}</div><h3>${safe(title)}</h3><p>${safe(subtitle)}</p>${action?`<button class="btn btn-primary" data-action="${action}" ${action==='add'?'data-kind="property"':''} type="button">${icon('plus')}${safe(actionName||'Add new')}</button>`:''}</div>`;}
const propOpts=(includeAll=true)=>`${includeAll?'<option value="all">All properties</option>':''}${db.properties.map(p=>`<option value="${safe(p.id)}" ${ui.property===p.id?'selected':''}>${safe(p.name)}</option>`).join('')}`;
function propertySelect(){return db.properties.length>1?`<select id="propertyFilter" class="select" aria-label="Filter by property">${propOpts()}</select>`:'';}
function filterBySearch(items,getText){const q=ui.search.trim().toLowerCase();return !q?items:items.filter(x=>getText(x).toLowerCase().includes(q));}
function rowActions(editKind,entityId,additional=''){return `<div class="row-actions">${additional}<button class="table-action" data-action="edit" data-kind="${editKind}" data-id="${safe(entityId)}" type="button">Edit</button></div>`;}
function shellTable(head,body,emptyText='Nothing to show yet'){return `<div class="table-shell"><div class="table-scroll"><table class="data-table"><thead><tr>${head.map(h=>`<th>${safe(h)}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${head.length}" style="text-align:center;padding:40px;color:#9aa6b5">${safe(emptyText)}</td></tr>`}</tbody></table></div></div>`;}
function setRoute(route,tab=''){if(route==='more'&&tab==='reports'){route='reports';tab='';}ui.route=ROUTES.includes(route)?route:'overview';ui.moreTab=tab;ui.search='';el('globalSearch').value='';const hash=ui.route==='more'&&tab?`more/${tab}`:ui.route;history.replaceState(null,'','#'+hash);closeMenu();render();window.scrollTo({top:0,behavior:'instant'});}
function closeMenu(){el('sidebar').classList.remove('open');el('sidebarBackdrop').hidden=true;}
function updateChrome(){
 const title={overview:'Overview',properties:'Properties',units:'Units',tenants:'Residents',leases:'Leases',rent:'Rent & payments',expenses:'Expenses',maintenance:'Maintenance',tasks:'Tasks',calendar:'Calendar',reports:'Reports',more:'More'}[ui.route];
 el('crumbPage').textContent=title+(ui.route==='more'&&ui.moreTab?' / '+({analyzer:'Deal Analyzer',reports:'Reports',settings:'Settings',cloud:'Cloud Sync',activity:'Activity'}[ui.moreTab]||ui.moreTab):'');
 el('workspaceName').textContent=db.settings.name||'My Portfolio';el('workspaceInitial').textContent=(db.settings.name||'M').slice(0,1).toUpperCase();
 el('userAvatar').textContent=(db.settings.name||'My Portfolio').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
 document.querySelectorAll('.nav-item').forEach(btn=>btn.classList.toggle('active',btn.dataset.route===ui.route));
 const due=ledger(monthNow()).filter(x=>x.remaining>.001).length;const work=db.maintenance.filter(x=>x.status!=='Completed').length;
 el('rentNavCount').textContent=due;el('rentNavCount').hidden=!due;
 el('maintenanceNavCount').textContent=work;el('maintenanceNavCount').hidden=!work;
}
function render(){updateChrome();const page={overview:renderOverview,properties:renderProperties,units:renderUnits,tenants:renderTenants,leases:renderLeases,rent:renderRent,expenses:renderExpenses,maintenance:renderMaintenance,tasks:renderTasks,calendar:renderCalendar,reports:renderReports,more:renderMore}[ui.route]();el('mainContent').innerHTML=page;hydrateIcons(el('mainContent'));window.EstateSelects?.enhance(el('mainContent'));if(ui.route==='more'&&ui.moreTab==='analyzer')updateCalc();}
function toast(msg,kind='success'){const div=document.createElement('div');div.className=`toast ${kind==='error'?'error':''}`;div.textContent=msg;el('toastRoot').append(div);setTimeout(()=>div.remove(),4000);}
function overviewMetric(value,label,route,description=''){
 const details=description?`<span class="pms-metric-hint">${safe(description)}</span>`:'';
 return `<button type="button" class="pms-metric" data-route="${route}" aria-label="${safe(label)}: ${safe(String(value).replace(/<[^>]*>/g,''))}; open ${safe(route)}"><span class="pms-metric-top"><span class="pms-metric-value">${value}</span><span class="pms-metric-arrow" aria-hidden="true">${icon('arrow-up-right')}</span></span><span class="pms-metric-label">${safe(label)}</span>${details}</button>`;
}
function overviewGroup(title,sub,metrics,foot){return `<section class="pms-group" aria-label="${safe(title)} summary"><div class="pms-group-head"><h2>${safe(title)}</h2><span>${safe(sub)}</span></div><div class="pms-metric-grid">${metrics.join('')}</div><div class="pms-group-foot">${foot}</div></section>`;}
function overviewShortcut(label,iconName,route,kind='',emphasis=false){const attributes=kind?`data-action="add" data-kind="${kind}"`:`data-route="${route}"`;return `<button type="button" class="pms-shortcut${emphasis?' is-primary':''}" ${attributes}>${icon(iconName)}<span>${safe(label)}</span><span class="pms-shortcut-arrow" aria-hidden="true">${icon('arrow-up-right')}</span></button>`;}
function renderOverview(){
 const propList=ui.property==='all'?db.properties:db.properties.filter(p=>p.id===ui.property);
 const allUnits=onlyProp(db.units,u=>u.propertyId);
 const units=allUnits.filter(u=>u.status!=='offline');
 const occupied=units.filter(u=>unitState(u)==='Occupied').length;
 const vacant=units.filter(u=>unitState(u)==='Vacant').length;
 const reserved=units.filter(u=>unitState(u)==='Reserved').length;
 const offline=allUnits.filter(u=>u.status==='offline').length;
 const occupancy=units.length?100*occupied/units.length:0;
 const current=financialSummary(monthNow());
 const open=onlyProp(db.maintenance,w=>w.propertyId).filter(w=>w.status!=='Completed');
 const priority=open.filter(w=>w.priority==='Urgent'||w.priority==='High');
 const expiry=scopedLeases().filter(l=>l.status==='active'&&l.end>=localToday()&&l.end<=plusDays(localToday(),60)).sort((a,b)=>a.end.localeCompare(b.end));
 const tasks=onlyProp(db.tasks,t=>t.propertyId).filter(t=>!t.done).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));
 const unpaid=current.rows.filter(l=>l.remaining>.001).sort((a,b)=>b.remaining-a.remaining);
 const paidPct=current.due?100*current.paid/current.due:0;
 const monthExpense=onlyProp(db.expenses,x=>x.propertyId).filter(x=>x.date?.slice(0,7)===monthNow()).reduce((sum,x)=>sum+(+x.amount||0),0);
 const residents=new Set(scopedLeases().filter(l=>l.status==='active'&&l.start<=localToday()&&l.end>=localToday()).map(l=>l.tenantId)).size;
 const dateLabel=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
 const sections=[
  overviewGroup('Portfolio','UNIT STATUS',[
   overviewMetric(propList.length,'Properties','properties'),
   overviewMetric(allUnits.length,'Total units','units'),
   overviewMetric(occupied,'Occupied','units'),
   overviewMetric(vacant,'Vacant','units')
  ],`<span class="pms-foot-note">${units.length?percent(occupancy):'—'} occupied</span><span class="pms-foot-divide">·</span><span>${residents} residents</span><span class="pms-foot-divide">·</span><span>${reserved} reserved</span><span class="pms-foot-divide">·</span><span>${offline} offline</span>`),
  overviewGroup('Rent & payments',fmtMonth(monthNow()).toUpperCase(),[
   overviewMetric(money(current.due),'Expected','rent'),
   overviewMetric(money(current.paid),'Collected','rent'),
   overviewMetric(money(current.balance),'Outstanding','rent'),
   overviewMetric(current.due?percent(paidPct):'—','Collection rate','rent')
  ],`<span class="pms-foot-note">${current.rows.length} scheduled lease${current.rows.length===1?'':'s'}</span><span class="pms-foot-divide">·</span><span>${money(monthExpense)} expenses recorded</span>`),
  overviewGroup('Operations','ACTION CENTER',[
   overviewMetric(open.length,'Open work orders','maintenance'),
   overviewMetric(priority.length,'High priority','maintenance'),
   overviewMetric(expiry.length,'Leases ending','leases','Next 60 days'),
   overviewMetric(tasks.length,'Open tasks','tasks')
  ],`<span class="pms-foot-note">Updated from your records</span><span class="pms-foot-divide">·</span><span>Open a tile for details</span>`)
 ];
 let attention=[];
 unpaid.slice(0,2).forEach(l=>attention.push({icon:'wallet',title:`Rent outstanding · ${tenantName(l.tenantId)}`,sub:`${money(l.remaining)} · ${unitName(l.unitId)}`,route:'rent'}));
 priority.slice(0,2).forEach(w=>attention.push({icon:'wrench',title:w.title,sub:`${unitName(w.unitId)} · ${w.priority} priority`,route:'maintenance'}));
 if(!priority.length)open.slice(0,1).forEach(w=>attention.push({icon:'wrench',title:w.title,sub:`${unitName(w.unitId)} · ${w.status}`,route:'maintenance'}));
 expiry.slice(0,2).forEach(l=>attention.push({icon:'calendar-days',title:`Lease ending · ${tenantName(l.tenantId)}`,sub:`${fmtDate(l.end)} · ${unitName(l.unitId)}`,route:'leases'}));
 tasks.slice(0,2).forEach(t=>attention.push({icon:'check-check',title:t.title,sub:`${propName(t.propertyId)}${t.dueDate?' · Due '+fmtShortDate(t.dueDate):''}`,route:'tasks'}));
 const propertyRows=propList.slice(0,5).map(p=>{const pUnits=db.units.filter(u=>u.propertyId===p.id),available=pUnits.filter(u=>u.status!=='offline');const count=available.filter(u=>unitState(u)==='Occupied').length;return `<button class="pms-property-line" type="button" data-action="view-property" data-id="${safe(p.id)}"><span class="pms-property-symbol">${icon('building-2')}</span><span class="pms-property-info"><strong>${safe(p.name)}</strong><small>${safe([p.city,p.region].filter(Boolean).join(', '))} · ${pUnits.length} unit${pUnits.length===1?'':'s'}</small></span><span class="pms-property-occ"><strong>${count} / ${available.length}</strong><small>occupied</small></span>${icon('chevron-right')}</button>`;}).join('');
 const shortcuts=[
  overviewShortcut('Add property','building-2','','property',true),
  overviewShortcut('New resident','users-round','','tenant'),
  overviewShortcut('New lease','file-signature','','lease'),
  overviewShortcut('Record payment','wallet','','payment',true),
  overviewShortcut('Create work order','wrench','','maintenance'),
  `<button type="button" class="pms-shortcut is-primary" data-action="open-unit-board">${icon('door-open')}<span>Unit status board</span><span class="pms-shortcut-arrow" aria-hidden="true">${icon('arrow-up-right')}</span></button>`
 ].join('');
 const noProperties=!db.properties.length;
 return `<div class="pms-dashboard">
 ${pageHeader('PROPERTY OPERATIONS','Overview',`Your portfolio at a glance · ${dateLabel}`,`${propertySelect()}<button type="button" class="btn btn-secondary" data-route="calendar">${icon('calendar-days')} Calendar</button>`)}
 ${noProperties?`<div class="pms-onboarding"><span class="pms-onboarding-icon">${icon('building-2')}</span><div><strong>Start with your first property</strong><p>Everything starts empty. Add a property to begin tracking units, residents, rent and day-to-day operations.</p></div><button type="button" class="btn btn-primary" data-action="add" data-kind="property">${icon('plus')} Add property</button></div>`:''}
 <div class="pms-summary-grid">${sections.join('')}</div>
 <div class="pms-action-heading"><h2>Quick actions</h2><span>Common workflows, one click away</span></div>
 <div class="pms-shortcut-grid">${shortcuts}</div>
 <div class="pms-bottom-grid">
  <section class="panel pms-bottom-panel"><div class="pms-bottom-heading"><div><h2>Needs attention</h2><p>Outstanding items from your workspace</p></div><button type="button" class="text-link" data-route="tasks">View tasks →</button></div>
   ${attention.length?`<div class="pms-attention-list">${attention.slice(0,5).map(a=>`<button type="button" class="pms-attention-item" data-route="${a.route}"><span class="pms-attention-icon">${icon(a.icon)}</span><span><strong>${safe(a.title)}</strong><small>${safe(a.sub)}</small></span><span class="pms-attention-open">${icon('chevron-right')}</span></button>`).join('')}</div>`:`<div class="pms-quiet-empty">${noProperties?'Add a property to start tracking your portfolio.':'Nothing needs your attention right now.'}</div>`}
  </section>
  <section class="panel pms-bottom-panel"><div class="pms-bottom-heading"><div><h2>Property snapshot</h2><p>Occupancy by property</p></div><button type="button" class="text-link" data-route="properties">All properties →</button></div>
   ${propertyRows?`<div class="pms-property-list">${propertyRows}</div>`:'<div class="pms-quiet-empty">No properties added yet.</div>'}
  </section>
 </div>
 <div class="footer-note">Figures are based on manually recorded information. Monthly rent charges are not prorated for partial months; EstateDock does not process payments automatically.</div>
 </div>`;
}
function renderProperties(){let props=filterBySearch(ui.property==='all'?db.properties:db.properties.filter(p=>p.id===ui.property),p=>p.name+' '+p.address+' '+p.city+' '+p.region);
 return `${pageHeader('PORTFOLIO','Properties','Organize single-family homes, duplexes, triplexes, fourplexes, and apartment buildings.',`<button class="btn btn-primary" data-action="add" data-kind="property">${icon('plus')} Add property</button>`)}<div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<span class="toolbar-hint">${props.length} ${props.length===1?'property':'properties'}</span></div></div>${props.length?`<div class="grid-cards">${props.map(p=>{const units=db.units.filter(u=>u.propertyId===p.id),occupied=units.filter(u=>unitState(u)==='Occupied').length,monthly=units.reduce((s,u)=>s+(+activeLease(u.id)?.rent||0),0);return `<article class="property-card"><div class="property-card-top"><span class="property-card-icon">${icon('building-2')}</span>${badge(p.type,'info')}</div><h3>${safe(p.name)}</h3><p class="address">${safe(p.address)} · ${safe(p.city)}, ${safe(p.region)}</p><div class="property-card-stats"><div><small>Occupancy</small><strong>${occupied} of ${units.length} units</strong></div><div><small>Active monthly rent</small><strong>${money(monthly)}</strong></div></div><div class="property-card-actions"><button class="text-link" data-action="view-property" data-id="${p.id}">View units →</button><div class="row-actions"><button class="table-action" data-action="edit" data-kind="property" data-id="${p.id}">Edit</button><button class="table-action" data-action="delete" data-kind="property" data-id="${p.id}">Delete</button></div></div></article>`;}).join('')}</div>`:emptyView('No properties match','Add a property or clear your search to get started.','add','Add property')}`;
}
function renderUnits(){let units=filterBySearch(rentalUnits().concat(onlyProp(db.units,u=>u.propertyId).filter(u=>u.status==='offline')),u=>u.label+' '+propName(u.propertyId)+' '+(tenantName(activeLease(u.id)?.tenantId)||''));units=[...new Map(units.map(u=>[u.id,u])).values()];
 const occupied=units.filter(u=>unitState(u)==='Occupied').length;
 const body=units.map(u=>{const l=activeLease(u.id),status=unitState(u);return `<tr><td><div class="cell-unit"><span class="mini-icon">${icon('door-open')}</span><div><div class="cell-main">${safe(u.label)}</div><div class="cell-sub">${safe(propName(u.propertyId))}</div></div></div></td><td>${statusBadge(status)}</td><td><div class="cell-main">${l?safe(tenantName(l.tenantId)):'—'}</div><div class="cell-sub">${l?'Current resident':'No active lease'}</div></td><td class="money-cell">${l?money(l.rent):(u.marketRent==null?'—':money(u.marketRent))}</td><td>${u.beds==null?'—':safe(u.beds)} bd · ${u.baths==null?'—':safe(u.baths)} ba</td><td>${l?fmtDate(l.end):'—'}</td><td>${rowActions('unit',u.id,`${!l&&u.status!=='offline'?`<button class="table-action" data-action="add" data-kind="lease" data-unit="${u.id}">Lease</button>`:''}<button class="table-action" data-action="delete" data-kind="unit" data-id="${u.id}">Delete</button>`)}</td></tr>`;}).join('');
 const board=`<div class="unit-board">${units.map(u=>{const status=unitState(u),l=activeLease(u.id);return `<button class="unit-tile ${status.toLowerCase()}" data-action="edit" data-kind="unit" data-id="${u.id}" aria-label="Edit ${safe(u.label)}"><div class="unit-tile-top"><span class="unit-number">${safe(u.label)}</span>${statusBadge(status)}</div><div class="unit-property">${safe(propName(u.propertyId))}</div><div class="unit-tenant">${l?safe(tenantName(l.tenantId)):'No current resident'}</div><div class="unit-tile-foot"><span>${l?money(l.rent):(u.marketRent==null?'—':money(u.marketRent))} / mo</span><span>${u.beds==null?'—':safe(u.beds)} bd · ${u.baths==null?'—':safe(u.baths)} ba</span></div></button>`;}).join('')}</div>`;
 return `${pageHeader('INVENTORY','Units','Track occupancy, market rent, residents, and availability across your portfolio.',`<button class="btn btn-primary" data-action="add" data-kind="unit">${icon('plus')} Add unit</button>`)}<div class="monthly-breakdown"><div class="small-stat"><small>Total units</small><strong>${units.length}</strong><span>Across selected properties</span></div><div class="small-stat"><small>Occupied</small><strong>${occupied}</strong><span>${percent(units.length?occupied/units.length*100:0)} currently occupied</span></div><div class="small-stat"><small>Vacant / reserved / offline</small><strong>${units.length-occupied}</strong><span>Not presently occupied</span></div></div><div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<span class="toolbar-hint">${units.length} units</span></div><div class="view-switch" role="group" aria-label="Unit display"><button class="${ui.unitView==='board'?'selected':''}" data-action="unit-board">Board</button><button class="${ui.unitView==='list'?'selected':''}" data-action="unit-list">List</button></div></div>${!units.length?emptyView('No units yet','Add your first property and its units.','add','Add a property'):ui.unitView==='board'?board:shellTable(['Unit','Status','Resident','Monthly rent','Layout','Lease end','Actions'],body,'No units yet.')}`;
}
function renderTenants(){let tenants=onlyProp(db.tenants,t=>{const current=db.leases.find(l=>l.tenantId===t.id&&l.status==='active'&&l.start<=localToday()&&l.end>=localToday());return getLeaseUnit(current)?.propertyId;});if(ui.property==='all')tenants=db.tenants;
 tenants=filterBySearch(tenants,t=>[t.name,t.preferredName,t.email,t.phone,t.alternatePhone,t.mailingAddress].join(' '));const body=tenants.map(t=>{const leases=db.leases.filter(l=>l.tenantId===t.id),current=leases.find(l=>l.status==='active'&&l.start<=localToday()&&l.end>=localToday());return `<tr><td><button class="resident-name" data-action="resident-profile" data-id="${t.id}">${safe(t.name)}</button><div class="cell-sub">${safe(t.preferredName&&t.preferredName!==t.name?'Goes by '+t.preferredName:t.email||'No email on file')}</div></td><td><div>${safe(t.phone||'—')}</div><div class="cell-sub">${safe(t.email||'')}</div></td><td>${current?safe(unitName(current.unitId)):'—'}</td><td>${statusBadge(current?'Active':leases.length?'Former':'Unassigned')}</td><td>${current?money(current.rent):'—'}</td><td><div class="row-actions"><button class="table-action" data-action="resident-profile" data-id="${t.id}">Profile</button><button class="table-action" data-action="edit" data-kind="tenant" data-id="${t.id}">Edit</button><button class="table-action" data-action="delete" data-kind="tenant" data-id="${t.id}">Delete</button></div></td></tr>`;}).join('');
 return `${pageHeader('RESIDENT DIRECTORY','Residents','Contact profiles, emergency details, and linked lease history for each resident.',`<button class="btn btn-primary" data-action="add" data-kind="tenant">${icon('plus')} Add resident</button>`)}<div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<span class="toolbar-hint">${tenants.length} residents</span></div></div>${shellTable(['Resident','Contact','Current unit','Status','Monthly rent','Actions'],body,'No residents found.')}`;
}
function profileValue(label,v){return `<div class="profile-item"><span>${safe(label)}</span><strong>${safe(v===0?'0':v||'—')}</strong></div>`;}
function showResidentProfile(tenantId){const t=find('tenants',tenantId);if(!t)return;const leases=db.leases.filter(l=>l.tenantId===t.id).sort((a,b)=>b.start.localeCompare(a.start));const live=leases.find(l=>l.status==='active'&&l.start<=localToday()&&l.end>=localToday());const payments=db.payments.filter(p=>leases.some(l=>l.id===p.leaseId)).sort((a,b)=>b.date.localeCompare(a.date));const paymentTotal=payments.reduce((sum,p)=>sum+(+p.amount||0),0);const communications=db.communications.filter(c=>c.tenantId===t.id).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
 const currentUnit=live?unitName(live.unitId):'No active lease';const body=`<div class="resident-profile">
 <div class="resident-profile-header"><div class="resident-avatar">${safe((t.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase())}</div><div><h3>${safe(t.name)}</h3><p>${safe(t.preferredName?'Preferred name: '+t.preferredName+' · ':'')}${safe(currentUnit)}</p></div>${statusBadge(live?'Active resident':leases.length?'Former resident':'No lease')}</div>
 <div class="profile-section"><h4>Contact information</h4><div class="profile-grid">${profileValue('Primary phone',t.phone)}${profileValue('Alternate phone',t.alternatePhone)}${profileValue('Email',t.email)}${profileValue('Additional email',t.secondaryEmail)}${profileValue('Preferred contact',t.contactPreference)}${profileValue('Mailing address',t.mailingAddress)}${profileValue('Preferred language',t.language)}</div></div>
 <div class="profile-section"><h4>Emergency contact</h4><div class="profile-grid">${profileValue('Contact name',t.emergencyName)}${profileValue('Relationship',t.emergencyRelationship)}${profileValue('Phone',t.emergencyPhone)}${profileValue('Email',t.emergencyEmail)}</div></div>
 <div class="profile-section"><h4>Household & property details</h4><div class="profile-grid">${profileValue('Other occupants',t.occupants)}${profileValue('Vehicle / parking',t.vehicles)}${profileValue('Pets',t.pets)}${profileValue('Preferred notice method',t.noticePreference)}</div></div>
 <div class="profile-section"><h4>Leases & payment history</h4><div class="profile-grid">${profileValue('Leases on record',leases.length)}${profileValue('Recorded payments',payments.length)}${profileValue('Total received (all time)',money(paymentTotal))}${profileValue('Current unit',currentUnit)}</div>
 ${leases.length?`<div class="resident-history">${leases.map(l=>`<div><strong>${safe(unitName(l.unitId))}</strong><span>${fmtDate(l.start)} – ${fmtDate(l.end)} · ${money(l.rent)}/month</span></div>`).join('')}</div>`:'<p class="small-muted">No leases recorded.</p>'}</div>
 <div class="profile-section"><div class="profile-section-heading"><h4>Contact history</h4><button class="btn btn-secondary" data-action="add" data-kind="communication" data-tenant="${t.id}">${icon('plus')} Log contact</button></div>
 ${communications.length?`<div class="resident-history">${communications.map(c=>`<div><div><strong>${safe(c.channel||'Contact')} · ${safe(c.subject||'Untitled')}</strong><div class="cell-sub">${fmtDate(c.date)}${c.notes?' · '+safe(c.notes):''}</div>${c.followUp?`<div class="cell-sub">Follow-up: ${fmtDate(c.followUp)}</div>`:''}</div><span><button class="table-action" data-action="edit" data-kind="communication" data-id="${c.id}">Edit</button><button class="table-action" data-action="delete" data-kind="communication" data-id="${c.id}">Delete</button></span></div>`).join('')}</div>`:'<p class="small-muted">No calls, emails or conversations logged yet.</p>'}</div>
 ${t.notes?`<div class="profile-section"><h4>Internal notes</h4><p class="resident-notes">${safe(t.notes)}</p></div>`:''}
 <div class="note">Store only information you need for lawful property operations. Do not enter Social Security numbers, full ID numbers, financial account details, or access codes here.</div>
 <div class="split-actions"><button class="btn btn-secondary" data-action="edit" data-kind="tenant" data-id="${t.id}">Edit resident</button>${live?`<button class="btn btn-secondary" data-action="payment-history" data-id="${live.id}">View rent payments</button>`:''}</div></div>`;
 openInfo('Resident profile',body);
}
function renderLeases(){let leases=filterBySearch(scopedLeases(),l=>tenantName(l.tenantId)+' '+unitName(l.unitId));leases.sort((a,b)=>b.start.localeCompare(a.start));
 const body=leases.map(l=>{const status=l.status!=='active'?'Ended':l.start>localToday()?'Future':l.end<localToday()?'Expired':'Active';return `<tr><td><div class="cell-main">${safe(tenantName(l.tenantId))}</div><div class="cell-sub">Resident</div></td><td>${safe(unitName(l.unitId))}</td><td>${statusBadge(status)}</td><td>${fmtDate(l.start)}</td><td>${fmtDate(l.end)}</td><td class="money-cell">${money(l.rent)}</td><td>${safe(String(l.dueDay||1))}${l.dueDay===1?'st':''} monthly</td><td>${rowActions('lease',l.id,`<button class="table-action" data-action="end-lease" data-id="${l.id}">End</button>`)}</td></tr>`;}).join('');
 return `${pageHeader('LEASE MANAGEMENT','Leases','Track agreement dates, rent amounts, due dates, and resident assignments.',`<button class="btn btn-primary" data-action="add" data-kind="lease">${icon('plus')} New lease</button>`)}<div class="alert info">Rent charges are scheduled for any month a lease overlaps; partial months are not prorated. Lease documents and legally binding e-signatures are not generated.</div><div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<span class="toolbar-hint">${leases.length} leases</span></div></div>${shellTable(['Resident','Unit','Status','Start','End','Rent','Due','Actions'],body,'No leases found.')}`;
}
function renderRent(){const sums=financialSummary(ui.month);let rows=filterBySearch(sums.rows,l=>tenantName(l.tenantId)+' '+unitName(l.unitId));rows=rows.filter(l=>ui.rentFilter==='all'||(ui.rentFilter==='outstanding'&&l.remaining>.001)||(ui.rentFilter==='paid'&&l.remaining<=.001));
 const body=rows.map(l=>{const s=l.remaining<=.001?'Paid':l.paid>0?'Partial':ui.month<monthNow()?'Overdue':'Outstanding';return `<tr><td><div class="cell-main">${safe(tenantName(l.tenantId))}</div><div class="cell-sub">${safe(unitName(l.unitId))}</div></td><td>${statusBadge(s)}</td><td class="money-cell">${money(l.due)}</td><td class="money-cell">${money(l.paid)}</td><td class="money-cell ${l.remaining?'text-danger':'text-success'}">${money(l.remaining)}</td><td>${rowActions('lease',l.id,`<button class="table-action" data-action="add" data-kind="payment" data-lease="${l.id}">Record</button><button class="table-action" data-action="payment-history" data-id="${l.id}">History</button>`)}</td></tr>`;}).join('');
 return `${pageHeader('REVENUE OPERATIONS','Rent & payments','Record rent received, review unpaid balances, and export your rent roll.',`<button class="btn btn-secondary" data-action="export-rent">${icon('download')} Export CSV</button><button class="btn btn-primary" data-action="add" data-kind="payment">${icon('plus')} Record payment</button>`)}<div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<div class="month-switch"><button data-action="month-prev" aria-label="Previous month">${icon('chevron-left')}</button><strong>${fmtMonth(ui.month)}</strong><button data-action="month-next" aria-label="Next month">${icon('chevron-right')}</button></div></div><select class="select" id="rentStatusFilter" aria-label="Filter rent status"><option value="all" ${ui.rentFilter==='all'?'selected':''}>All balances</option><option value="outstanding" ${ui.rentFilter==='outstanding'?'selected':''}>Outstanding</option><option value="paid" ${ui.rentFilter==='paid'?'selected':''}>Paid in full</option></select></div>
 <div class="monthly-breakdown"><div class="small-stat"><small>Scheduled rent</small><strong>${money(sums.due)}</strong><span>${sums.rows.length} lease charges</span></div><div class="small-stat"><small>Recorded payments</small><strong class="text-success">${money(sums.paid)}</strong><span>${percent(sums.due?sums.paid/sums.due*100:0)} of scheduled rent</span></div><div class="small-stat"><small>Remaining balance</small><strong class="${sums.balance?'text-danger':''}">${money(sums.balance)}</strong><span>Does not include late fees</span></div></div>
 ${shellTable(['Resident / unit','Status','Scheduled','Paid','Balance','Actions'],body,'No lease charges for the selected month.')}<p class="tip">Payment amounts are entered manually. This workspace does not connect to banks, send invoices, process funds, or reconcile deposits automatically.</p>`;
}
function renderExpenses(){
 const monthly=onlyProp(db.expenses,x=>x.propertyId).filter(x=>x.date?.slice(0,7)===ui.month);
 const rows=filterBySearch(monthly,x=>x.category+' '+x.payee+' '+x.note+' '+propName(x.propertyId)).sort((a,b)=>b.date.localeCompare(a.date));
 const amount=monthly.reduce((n,x)=>n+(+x.amount||0),0), collected=financialSummary(ui.month).paid;
 const body=rows.map(x=>`<tr><td>${fmtDate(x.date)}</td><td><div class="cell-main">${safe(x.category)}</div><div class="cell-sub">${safe(x.payee||'')}</div></td><td>${safe(propName(x.propertyId))}</td><td class="money-cell">${preciseMoney(x.amount)}</td><td>${safe(x.note||'—')}</td><td>${rowActions('expense',x.id,`<button class="table-action" data-action="delete" data-kind="expense" data-id="${x.id}">Delete</button>`)}</td></tr>`).join('');
 return `${pageHeader('PROPERTY EXPENSES','Expenses','Record operating costs, mortgage payments, and other cash outflows.',`<button class="btn btn-secondary" data-action="export-expenses">${icon('download')} Export CSV</button><button class="btn btn-primary" data-action="add" data-kind="expense">${icon('plus')} Add expense</button>`)}
 <div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<div class="month-switch"><button data-action="month-prev">${icon('chevron-left')}</button><strong>${fmtMonth(ui.month)}</strong><button data-action="month-next">${icon('chevron-right')}</button></div></div></div>
 <div class="monthly-breakdown"><div class="small-stat"><small>Recorded expenses</small><strong>${money(amount)}</strong><span>${monthly.length} expense entries</span></div><div class="small-stat"><small>Rent payments received</small><strong>${money(collected)}</strong><span>For selected month</span></div><div class="small-stat"><small>Net recorded cash movement</small><strong class="${collected-amount<0?'text-danger':'text-success'}">${money(collected-amount)}</strong><span>Received rent less logged expenses</span></div></div>
 ${shellTable(['Date','Category / payee','Property','Amount','Notes','Actions'],body,'No expenses recorded for this month.')}<p class="tip">Record mortgage payments and other costs only when paid. Net recorded cash movement is not accounting profit, NOI, or cash-on-cash ROI; it excludes unrecorded expenses, deposits, and noncash tax items.</p>`;
}
function exportExpenses(){const records=onlyProp(db.expenses,x=>x.propertyId).filter(x=>x.date?.slice(0,7)===ui.month);const head=['Date','Property','Category','Payee','Amount','Notes'];downloadBlob(`estatedock-expenses-${ui.month}.csv`,[head,...records.map(x=>[x.date,propName(x.propertyId),x.category,x.payee,x.amount,x.note])].map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Expense CSV downloaded');}
function renderMaintenance(){const orders=filterBySearch(onlyProp(db.maintenance,w=>w.propertyId).filter(w=>ui.maintenanceFilter==='all'||w.status===ui.maintenanceFilter),w=>w.title+' '+unitName(w.unitId)+' '+w.description);orders.sort((a,b)=>(a.status==='Completed'?1:0)-(b.status==='Completed'?1:0)||({Urgent:0,High:1,Normal:2,Low:3}[a.priority]||2)-({Urgent:0,High:1,Normal:2,Low:3}[b.priority]||2));
 const body=orders.map(w=>`<tr><td><div class="cell-main">${safe(w.title)}</div><div class="cell-sub">${safe(w.description||'No description')}</div></td><td>${safe(unitName(w.unitId))}</td><td>${statusBadge(w.priority)}</td><td>${statusBadge(w.status)}</td><td>${safe(w.assignedTo||'Unassigned')}</td><td>${fmtDate(w.dueDate)}</td><td class="money-cell">${money(w.cost||0)}</td><td>${rowActions('maintenance',w.id,`${w.status!=='Completed'?`<button class="table-action" data-action="complete-work" data-id="${w.id}">Complete</button>`:''}`)}</td></tr>`).join('');
 return `${pageHeader('SERVICE DESK','Maintenance','Organize issues, repair costs, priorities, and resolution status.',`<button class="btn btn-primary" data-action="add" data-kind="maintenance">${icon('plus')} New work order</button>`)}<div class="monthly-breakdown"><div class="small-stat"><small>Open</small><strong>${orders.filter(x=>x.status==='Open').length}</strong><span>Awaiting action</span></div><div class="small-stat"><small>In progress</small><strong>${orders.filter(x=>x.status==='In progress').length}</strong><span>Being resolved</span></div><div class="small-stat"><small>Completed</small><strong>${orders.filter(x=>x.status==='Completed').length}</strong><span>Recorded work orders</span></div></div><div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<select id="maintenanceFilter" class="select" aria-label="Filter maintenance status">${['all','Open','In progress','Completed'].map(v=>`<option value="${v}" ${ui.maintenanceFilter===v?'selected':''}>${v==='all'?'All statuses':v}</option>`).join('')}</select></div></div>${shellTable(['Work order','Unit','Priority','Status','Assigned to','Due','Cost','Actions'],body,'No work orders found.')}`;
}
function renderTasks(){const tasks=filterBySearch(onlyProp(db.tasks,t=>t.propertyId),t=>t.title+' '+t.notes);tasks.sort((a,b)=>Number(a.done)-Number(b.done)||a.dueDate.localeCompare(b.dueDate));
 const body=tasks.map(t=>`<tr><td><div class="cell-main" style="${t.done?'text-decoration:line-through;color:#95a4b6':''}">${safe(t.title)}</div><div class="cell-sub">${safe(t.notes||'')}</div></td><td>${safe(propName(t.propertyId))}</td><td>${fmtDate(t.dueDate)}</td><td>${statusBadge(t.done?'Done':t.dueDate<localToday()?'Overdue':'Open')}</td><td><div class="row-actions"><button class="table-action" data-action="toggle-task" data-id="${t.id}">${t.done?'Reopen':'Complete'}</button><button class="table-action" data-action="edit" data-kind="task" data-id="${t.id}">Edit</button><button class="table-action" data-action="delete" data-kind="task" data-id="${t.id}">Delete</button></div></td></tr>`).join('');
 return `${pageHeader('DAILY OPERATIONS','Tasks','Keep recurring inspections, renewals, and follow-ups from slipping through the cracks.',`<button class="btn btn-primary" data-action="add" data-kind="task">${icon('plus')} Add task</button>`)}<div class="data-toolbar"><div class="toolbar-left">${propertySelect()}<span class="toolbar-hint">${tasks.filter(t=>!t.done).length} open tasks</span></div></div>${shellTable(['Task','Property','Due date','Status','Actions'],body,'No tasks found.')}`;
}
function renderCalendar(){const ym=ui.calendarMonth,[year,month]=ym.split('-').map(Number),first=new Date(year,month-1,1).getDay(),days=new Date(year,month,0).getDate();const evt=[];
 onlyProp(db.tasks,t=>t.propertyId).filter(t=>t.dueDate.slice(0,7)===ym).forEach(t=>evt.push({date:t.dueDate,title:t.title,kind:t.done?'positive':'warning'}));
 scopedLeases().forEach(l=>{if(l.start.slice(0,7)===ym)evt.push({date:l.start,title:'Move-in · '+tenantName(l.tenantId),kind:'positive'});if(l.end.slice(0,7)===ym)evt.push({date:l.end,title:'Lease ends · '+tenantName(l.tenantId),kind:'warning'});if(l.start<=`${ym}-${String(days).padStart(2,'0')}`&&l.end>=`${ym}-01`){const day=Math.min(+l.dueDay||1,days);evt.push({date:`${ym}-${String(day).padStart(2,'0')}`,title:'Rent due · '+unitName(l.unitId),kind:'info'});}});
 onlyProp(db.maintenance,w=>w.propertyId).filter(w=>w.status!=='Completed'&&w.dueDate?.slice(0,7)===ym).forEach(w=>evt.push({date:w.dueDate,title:'Repair · '+w.title,kind:'warning'}));
 let cells='';for(let i=0;i<Math.ceil((first+days)/7)*7;i++){const day=i-first+1,valid=day>=1&&day<=days,iso=`${ym}-${String(day).padStart(2,'0')}`,dayEvents=evt.filter(e=>e.date===iso);cells+=`<div class="cal-cell ${!valid?'other':''} ${valid&&iso===localToday()?'today':''}"><span class="cal-day">${valid?day:''}</span>${dayEvents.slice(0,2).map(e=>`<span class="cal-event ${e.kind}">${safe(e.title)}</span>`).join('')}${dayEvents.length>2?`<span class="small-muted">+${dayEvents.length-2} more</span>`:''}</div>`;}
 return `${pageHeader('SCHEDULE','Calendar','Lease changes, rent due dates, repair deadlines, and your tasks.',`${propertySelect()}`)}<div class="calendar-layout"><section class="panel panel-pad"><div class="panel-heading"><h2 class="panel-title">${fmtMonth(ym)}</h2><div class="month-switch"><button data-action="calendar-prev" aria-label="Previous month">${icon('chevron-left')}</button><button data-action="calendar-next" aria-label="Next month">${icon('chevron-right')}</button></div></div><div class="calendar-head">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(s=>`<span>${s}</span>`).join('')}</div><div class="calendar-grid">${cells}</div></section><section class="panel panel-pad"><div class="panel-heading"><h2 class="panel-title">This month's schedule</h2>${badge(evt.length+' events','info')}</div>${evt.length?evt.sort((a,b)=>a.date.localeCompare(b.date)).slice(0,18).map(e=>`<div class="mini-list-row"><span class="dot-icon">${icon('calendar-days')}</span><div class="mini-list-body"><div class="mini-list-title">${safe(e.title)}</div><div class="mini-list-sub">${fmtDate(e.date)}</div></div></div>`).join(''):'<p class="small-muted">No events scheduled this month.</p>'}</section></div>`;
}
function renderMore(){const tabs=[['','All tools'],['analyzer','Deal Analyzer'],['activity','Activity'],['cloud','Cloud Sync'],['settings','Settings']];
 const nav=`<div class="tab-bar">${tabs.map(([key,label])=>`<button class="tab ${ui.moreTab===key?'active':''}" data-more="${key}">${label}</button>`).join('')}</div>`;
 let body='';if(!ui.moreTab){body=`<div class="more-menu">${[['analyzer','chart-no-axes-combined','Deal Analyzer','Model purchases, financing, monthly cash flow, and return targets.'],['activity','activity','Activity Log','See operational changes recorded in this workspace.'],['cloud','cloud','Cloud Sync','Optional private account-based synchronization with Supabase.'],['settings','settings','Settings & Backups','Manage workspace preferences, export data, and restore records.']].map(([tab,ico,title,desc])=>`<button class="tool-card" data-more="${tab}"><span class="mini-icon">${icon(ico)}</span><span><div class="tool-title">${title}</div><div class="tool-desc">${desc}</div></span></button>`).join('')}</div>`;}
 else body=({analyzer:renderAnalyzer,activity:renderActivity,settings:renderSettings,cloud:renderCloud}[ui.moreTab]||renderSettings)();
 return `${pageHeader('MORE','Tools & settings','Investment analysis, reports, data management, and optional cloud synchronization.')}${nav}${body}`;
}
function calcField(label,name,value,type='number',other=''){return `<div class="field"><label for="an-${name}">${safe(label)}</label><input id="an-${name}" name="${name}" type="${type}" value="${safe(value)}" ${type==='number'?'inputmode="decimal"':''} ${other}></div>`;}
function calcSelect(label,name,value,opts){return `<div class="field"><label for="an-${name}">${safe(label)}</label><select id="an-${name}" name="${name}"><option value="" ${value===''?'selected':''}>Select…</option>${opts.map(([v,t])=>`<option value="${safe(v)}" ${String(v)===String(value)?'selected':''}>${safe(t)}</option>`).join('')}</select></div>`;}
function analyzerAdvancedFields(a){return `<div class="form-grid analyzer-advanced-grid">
 <div class="form-section-label">Additional loan & acquisition details</div>
 ${calcSelect('Financing','loanType',a.loanType,[['conventional','Conventional'],['fha','FHA']])}${calcSelect('Loan term','years',a.years,[[15,'15 years'],[20,'20 years'],[25,'25 years'],[30,'30 years']])}
 ${calcField('Closing costs (%)','closingPct',a.closingPct,'number','min="0" step=".5" placeholder="Default 3"')}${calcField('Upfront repairs ($)','repairs',a.repairs,'number','min="0" placeholder="Default 0"')}
 <div class="form-section-label">Tax, insurance & other housing costs</div>
 ${calcField('Property tax (% / year)','taxPct',a.taxPct,'number','min="0" step=".1" placeholder="Default 1.5"')}${calcField('Insurance ($ / month)','insurance',a.insurance,'number','min="0" placeholder="Default 225"')}
 ${calcField('Mortgage insurance (% / year)','miPct',a.miPct,'number','min="0" step=".05" placeholder="Default 1 (FHA 0.55)"')}${calcField('HOA ($ / month)','hoa',a.hoa,'number','min="0" placeholder="Default 0"')}
 ${a.loanType==='fha'?`<div class="field full checkbox-field"><input type="checkbox" name="financeUpfront" id="an-financeUpfront" ${a.financeUpfront?'checked':''}><label for="an-financeUpfront">Finance estimated FHA upfront MIP (1.75%)</label></div>`:''}
 <div class="form-section-label">Rental operations & costs</div>
 ${calcField('Rented units','occupied',a.occupied,'number','min="0" step="1" placeholder="Default: all units"')}${calcField('Vacancy rate (%)','vacancy',a.vacancy,'number','min="0" max="100" placeholder="Default 5"')}
 ${calcField('Maintenance (% of collected rent)','maintenance',a.maintenance,'number','min="0" placeholder="Default 10"')}${calcField('Major-repair reserves (%)','capex',a.capex,'number','min="0" placeholder="Default 5"')}
 ${calcField('Property management (%)','management',a.management,'number','min="0" placeholder="Default 0"')}${calcField('Owner utilities ($ / month)','utilities',a.utilities,'number','min="0" placeholder="Default 0"')}
 ${calcField('Other expenses ($ / month)','other',a.other,'number','min="0" placeholder="Default 0"')}
 <div class="form-section-label">Your targets</div>
 ${calcField('Target annual cash-on-cash ROI (%)','targetRoi',a.targetRoi,'number','min="0" placeholder="Default 12"')}${calcField('Target cash flow ($ / unit / month)','targetCash',a.targetCash,'number','min="0" placeholder="Default 100"')}
 </div>`;}
function dealSummary(r){return `<div class="deal-kpi-grid"><div class="deal-kpi"><span>Monthly cash flow</span><strong class="${r.flow<0?'text-danger':'text-success'}">${money(r.flow)}</strong></div><div class="deal-kpi"><span>Cash-on-cash return</span><strong class="${r.coc<0?'text-danger':'text-success'}">${percent(r.coc)}</strong></div><div class="deal-kpi"><span>Estimated cash invested</span><strong>${money(r.cashIn)}</strong></div><div class="deal-kpi"><span>Monthly payment</span><strong>${money(r.payment)}</strong></div></div>`;}
function renderAnalyzer(){const a=ui.analyzer,mode=ui.analyzerMode,assumed=effectiveDeal(a);
 const nav=`<div class="analyzer-mode-switch" role="group" aria-label="Deal analyzer mode"><button class="${mode==='quick'?'active':''}" data-action="analyzer-quick">Quick estimate</button><button class="${mode==='advanced'?'active':''}" data-action="analyzer-advanced">Advanced</button><button class="${mode==='compare'?'active':''}" data-action="analyzer-compare">Compare deals <span class="count-dot">${db.deals.length}</span></button></div>`;
 if(mode==='compare')return `${nav}${renderDealComparison()}`;
 return `${nav}<div class="alert info">${mode==='quick'?'Enter the price, units, rent, down payment and interest rate for a quick estimate. Other assumptions are listed below and can be adjusted in Advanced.':'Customize financing, expenses, rental assumptions and targets. Down payment and interest rate are always entered by you; optional fields use the labeled defaults.'} All amounts are estimates, not lender quotes.</div>
 <div class="calculator-layout analyzer-v2-layout"><section class="panel form-panel"><div class="analyzer-topline"><div><h3>${mode==='quick'?'Quick deal estimate':'Detailed deal analysis'}</h3><p class="panel-sub">No data is prefilled.</p></div><button class="btn btn-secondary" data-action="analyzer-${mode==='quick'?'advanced':'quick'}">${mode==='quick'?'Advanced →':'← Simple view'}</button></div>
 <div id="analyzerInputs"><div class="form-grid"><div class="field full"><label for="an-dealName">Deal name (optional, for comparison)</label><input id="an-dealName" name="dealName" type="text" maxlength="80" placeholder="e.g. Oak Street fourplex" value="${safe(a.dealName||'')}"></div>
 ${calcField('Purchase price ($)','price',a.price,'number','min="0" placeholder="e.g. 250000"')}${calcField('Number of units','units',a.units,'number','min="1" max="500" step="1" placeholder="e.g. 4"')}
 ${calcField('Monthly rent per unit ($)','rent',a.rent,'number','min="0" placeholder="e.g. 900"')}
 <div class="form-section-label">Your financing <span class="analyzer-field-note">Enter your actual planned terms</span></div>
 ${calcField('Down payment (%)','down',a.down,'number','min="0" max="100" step="any" placeholder="e.g. 5" required')}
 ${calcField('Interest rate (%)','rate',a.rate,'number','min="0" max="40" step="any" placeholder="e.g. 6.75" required')}</div>
 ${mode==='advanced'?analyzerAdvancedFields(a):`<div class="assumptions-strip"><strong>Other quick assumptions</strong><span>${safe(assumed.loanType==='fha'?'FHA':'Conventional')} · ${safe(assumed.years)}-year term · ${safe(assumed.closingPct)}% closing costs (down payment and interest are entered above)</span><span>${safe(assumed.vacancy)}% vacancy · ${safe(assumed.taxPct)}% property tax · ${money(assumed.insurance)}/month insurance · ${safe(assumed.miPct)}% mortgage insurance · ${safe(assumed.maintenance+assumed.capex)}% maintenance & capital reserves · ${safe(assumed.management)}% management fee</span><span>Additional expenses and upfront repairs, if entered, still apply. Open Advanced to review every assumption.</span><span>Owner-occupied financing assumed at purchase; returns model all units rented after moving out. Fully rented investment purchases may require substantially more down.</span></div>`}
 </div><div class="split-actions deal-actions"><button class="btn btn-primary" data-action="deal-save">${icon('plus')} ${ui.editingDealId?'Update saved deal':'Save deal'}</button><button class="btn btn-secondary" data-action="analyzer-new">New deal</button></div></section>
 <section class="panel calc-result"><h3 class="panel-title">Estimated performance</h3><p class="panel-sub" style="margin-bottom:17px">For the currently entered deal</p><div id="calcOutput"></div></section></div>
 <div class="tip">This quick screen assumes stabilized, long-term rental operations, equal rent in every unit, no rent increases, and no appreciation. It excludes lender cash-reserve requirements, acquisition-specific fees beyond the closing-cost assumption, and tax effects. The advanced mode supports properties with more than four units for rough modeling, not commercial-loan qualification.</div>`;
}
function updateCalc(){const out=el('calcOutput');if(!out)return;const a=ui.analyzer;if(!dealReady(a)){out.innerHTML='<div class="calculator-empty"><span class="calculator-empty-icon">'+icon('chart-no-axes-combined')+'</span><h3>Enter your deal details</h3><p>Enter the purchase price, number of units, monthly rent per unit, down payment percentage, and interest rate to calculate your projected return. No interest rate or down payment will be assumed.</p></div>';return;}
 const e=effectiveDeal(a),r=UnitMath.analyze(e);const rentTarget=n=>Number.isFinite(n)?money(Math.ceil(n)):'—';
 out.innerHTML=`${e.units>4?'<div class="alert warning">Five or more units typically require commercial financing. These numbers are rough projections, not a loan eligibility model.</div>':''}
 ${dealSummary(r)}<div class="divider"></div><div class="simple-metrics"><div><span>Rent collected after vacancy</span><strong>${money(r.collected)}/mo</strong></div><div><span>Operating reserves & management</span><strong>−${money(r.reserves)}/mo</strong></div><div><span>Mortgage, taxes, insurance & HOA</span><strong>−${money(r.payment)}/mo</strong></div><div><span>Other expenses</span><strong>−${money(r.extra)}/mo</strong></div><div><span>Rent needed for 12% cash-on-cash</span><strong>${rentTarget(UnitMath.analyze({...e,targetRoi:12}).targetRoiRent)}/unit</strong></div></div>
 ${ui.analyzerMode==='advanced'?`<div class="divider"></div><h3 class="panel-title" style="margin-bottom:10px">Detailed financing</h3><div class="simple-metrics"><div><span>Loan amount</span><strong>${money(r.loan)}</strong></div><div><span>Principal + interest monthly</span><strong>${money(r.loanResult.monthly)}</strong></div><div><span>Interest over full term</span><strong>${money(r.loanResult.interest)}</strong></div><div><span>Balance after 12 months</span><strong>${money(r.remainingYearOne)}</strong></div><div><span>Rent needed for ${safe(e.targetRoi)}% target ROI</span><strong>${rentTarget(r.targetRoiRent)}/unit</strong></div><div><span>Rent needed for ${money(e.targetCash)}/unit cash flow</span><strong>${rentTarget(r.targetUnitRent)}/unit</strong></div></div>`:''}
 <p class="small-muted" style="margin-top:14px">${ui.analyzerMode==='quick'?'Uses your entered interest rate and down payment, plus the other Quick assumptions shown on the left.':'Optional values left empty use the stated defaults; financing rate and down payment are never assumed.'} Cash invested excludes unspent liquid reserves. Property values may fall and real expenses may exceed this estimate.</p>`;
}
function renderDealComparison(){const deals=db.deals;const selected=deals.filter(d=>ui.selectedDeals.includes(d.id)).slice(0,3);
 return `<div class="compare-toolbar"><div><h3 class="panel-title">Compare saved opportunities</h3><p class="panel-sub">Save up to three deals to compare cash flow and cash-on-cash returns side by side.</p></div><button class="btn btn-primary" data-action="analyzer-quick">${icon('plus')} Analyze another deal</button></div>
 ${deals.length?`<div class="saved-deals">${deals.map(d=>{const a=effectiveDeal(d.input),ready=dealReady(d.input),r=ready?UnitMath.analyze(a):null,checked=ui.selectedDeals.includes(d.id);return `<article class="saved-deal ${checked?'chosen':''}"><div class="saved-deal-check"><input aria-label="Compare ${safe(d.name)}" type="checkbox" class="compare-check" data-id="${d.id}" ${checked?'checked':''}></div><div class="saved-deal-info"><strong>${safe(d.name)}</strong><span>${money(a.price)} · ${a.units} units · ${money(a.rent)}/unit</span></div><div class="saved-deal-roi">${ready?`<strong class="${r.coc<0?'text-danger':'text-success'}">${percent(r.coc)}</strong><small>${money(r.flow)}/mo</small>`:'<strong>Needs financing</strong><small>Open Edit to enter rate & down payment</small>'}</div><button class="table-action" data-action="deal-load" data-id="${d.id}">Edit</button><button class="table-action text-danger" data-action="deal-delete" data-id="${d.id}">Remove</button></article>`;}).join('')}</div>`:emptyView('No saved deals','Create a quick estimate and click Save deal to begin comparing opportunities.')}
 ${selected.length>=2?`${selected.some(d=>!dealReady(d.input))?'<div class="alert warning">Some older saved deals need an interest rate or down payment. Open Edit to provide these before comparing their returns.</div>':''}<div class="panel panel-pad deal-table-wrap"><h3 class="panel-title">Side-by-side comparison</h3><div class="table-scroll"><table class="data-table comparison-table"><thead><tr><th>Metric</th>${selected.map(d=>`<th>${safe(d.name)}</th>`).join('')}</tr></thead><tbody>${[
 ['Purchase price',d=>money(d.r.price)],['Rent / unit',d=>money(d.a.rent)],['Total units',d=>d.a.units],['Potential rent / month',d=>money(d.a.units*d.a.rent)],['Net collected / month',d=>money(d.r.collected)],['Total housing payment',d=>money(d.r.payment)],['Operating reserves / month',d=>money(d.r.reserves)],['Monthly cash flow',d=>money(d.r.flow)],['Annual cash flow',d=>money(d.r.flow*12)],['Cash invested',d=>money(d.r.cashIn)],['Cash-on-cash ROI',d=>percent(d.r.coc)],['Rent needed for 12% ROI',d=>money(d.targetRent)]
 ].map(([label,fn])=>`<tr><td>${label}</td>${selected.map(d=>{if(!dealReady(d.input))return '<td>—</td>';const a=effectiveDeal(d.input),r=UnitMath.analyze(a),v={a,r,targetRent:UnitMath.analyze({...a,targetRoi:12}).targetRoiRent};return `<td>${safe(fn(v))}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></div>`:`<div class="note compare-help">${deals.length?'Select two or three saved deals to view a side-by-side comparison.':'Your saved deals will appear here. Select two or three to compare.'}</div>`}
 <p class="tip">Comparison uses each deal's saved assumptions. These are projections, not appraisals, verified income statements, or investment recommendations.</p>`;
}
// REPORT STUDIO — record-backed, configurable, no generated sample rows.
const REPORT_TYPES={
 expenses:{label:'Expense report',desc:'Recorded expenses, ordered by payment date.',hint:'Expenses reflect manual records, not verified bank transactions.',defaultCols:['date','property','category','payee','amount','note'],dateKey:'date',cols:{date:['Payment date'],property:['Property'],category:['Category'],payee:['Payee / vendor'],amount:['Amount','money'],note:['Notes']}},
 property:{label:'Property report',desc:'Occupancy, rental portfolio details, and cash movement by property.',hint:'Occupancy is based on active leases today. Cash figures follow the chosen date range.',defaultCols:['property','address','type','units','occupied','vacant','occupancy','collected','expenses','net'],cols:{property:['Property'],address:['Address'],city:['City'],region:['State / province'],type:['Type'],units:['Total units','number'],occupied:['Occupied units','number'],vacant:['Vacant units','number'],occupancy:['Occupancy %','percent'],marketRent:['Market rent / mo','money'],collected:['Payments received','money'],expenses:['Expenses paid','money'],net:['Net recorded movement','money'],notes:['Notes']}},
 units:{label:'Unit report',desc:'Unit availability, asking rent, resident and lease details.',hint:'Unit status is as of today, not historical occupancy.',defaultCols:['property','unit','status','beds','baths','marketRent','resident','leaseEnd'],cols:{property:['Property'],unit:['Unit'],status:['Status'],beds:['Beds','number'],baths:['Baths','number'],sqft:['Square feet','number'],marketRent:['Market rent','money'],resident:['Resident'],leaseRent:['Lease rent','money'],leaseStart:['Lease start'],leaseEnd:['Lease end']}},
 residents:{label:'Resident directory',desc:'Contact list with optional household and emergency-contact fields.',hint:'Contains personal contact information. Only export and share with authorized people.',defaultCols:['resident','property','unit','phone','email','contactPreference'],cols:{resident:['Resident'],preferredName:['Preferred name'],property:['Property'],unit:['Unit'],phone:['Primary phone'],alternatePhone:['Alternate phone'],email:['Primary email'],secondaryEmail:['Additional email'],mailingAddress:['Mailing address'],language:['Preferred language'],contactPreference:['Preferred communication'],emergencyName:['Emergency contact'],emergencyRelationship:['Emergency relationship'],emergencyPhone:['Emergency phone'],emergencyEmail:['Emergency email'],occupants:['Authorized occupants'],vehicles:['Vehicles / parking'],pets:['Pets'],notes:['Internal notes']}},
 leases:{label:'Lease report',desc:'Lease terms, residents, deposits, and expiration dates.',hint:'Date filtering finds leases that overlap the selected range.',defaultCols:['property','unit','resident','status','start','end','rent','deposit'],cols:{property:['Property'],unit:['Unit'],resident:['Resident'],status:['Status'],start:['Start date'],end:['End date'],rent:['Monthly rent','money'],deposit:['Security deposit','money'],dueDay:['Due day','number']}},
 payments:{label:'Payment report',desc:'All manually logged rent payments and methods.',hint:'Shows payments recorded in the app; no bank verification.',defaultCols:['date','property','unit','resident','month','amount','method','note'],dateKey:'date',cols:{date:['Payment date'],property:['Property'],unit:['Unit'],resident:['Resident'],month:['Rent month'],amount:['Amount received','money'],method:['Method'],note:['Reference / notes']}},
 rentroll:{label:'Rent roll',desc:'Monthly charges, payments, and balances by lease.',hint:'Rent is charged in full for every overlapping lease month; this app does not prorate.',defaultCols:['month','property','unit','resident','rent','paid','balance','status'],cols:{month:['Rent month'],property:['Property'],unit:['Unit'],resident:['Resident'],rent:['Rent due','money'],paid:['Paid','money'],balance:['Outstanding','money'],status:['Payment status']}},
 maintenance:{label:'Maintenance report',desc:'Work orders, priority, scheduled date, and tracked costs.',hint:'Work-order costs are informational; they are not automatically added to the expense ledger.',defaultCols:['property','unit','title','priority','status','assignedTo','dueDate','cost'],dateKey:'dueDate',cols:{property:['Property'],unit:['Unit'],title:['Work order'],priority:['Priority'],status:['Status'],assignedTo:['Assigned to'],dueDate:['Due date'],cost:['Recorded cost','money'],description:['Description']}},
 tasks:{label:'Task report',desc:'Outstanding and completed property-related tasks.',hint:'Tasks with no due date are excluded when a date filter is applied.',defaultCols:['property','title','dueDate','status','notes'],dateKey:'dueDate',cols:{property:['Property'],title:['Task'],dueDate:['Due date'],status:['Status'],notes:['Notes']}},
 financial:{label:'Financial summary',desc:'Recorded rent received, expenses and net cash movement per property.',hint:'Net cash movement is not NOI, net income, or tax profit; missing expenses will overstate results.',defaultCols:['property','payments','expenses','net','collections','transactions'],cols:{property:['Property'],payments:['Rent received','money'],expenses:['Expenses paid','money'],net:['Net recorded movement','money'],collections:['Payment entries','number'],transactions:['Expense entries','number']}}
};
function reportCols(){const type=ui.report.type,schema=REPORT_TYPES[type];const selected=ui.report.columnsByType[type];return (selected===undefined?schema.defaultCols:selected).filter(key=>schema.cols[key]);}
function reportDateMatch(date,from=ui.report.from,to=ui.report.to){return (!from||!!date&&date>=from)&&(!to||!!date&&date<=to);}
function reportPropertyMatch(pid){return ui.report.property==='all'||pid===ui.report.property;}
function reportMonthRange(){const from=ui.report.from?.slice(0,7)||ui.report.to?.slice(0,7)||monthNow(),to=ui.report.to?.slice(0,7)||from;if(from>to)return [];const months=[];let m=from;while(m<=to&&months.length<120){months.push(m);m=plusMonths(m,1);}return months;}
function reportData(){const type=ui.report.type,rows=[];const inProp=p=>reportPropertyMatch(p.propertyId);const inRange=(date)=>reportDateMatch(date);const inRangeMonth=month=>reportDateMatch(month+'-01',ui.report.from?.slice(0,7)+'-01'||'',ui.report.to?.slice(0,7)+'-31'||'');
 if(type==='expenses')db.expenses.filter(x=>inProp(x)&&inRange(x.date)).forEach(x=>rows.push({date:x.date,property:propName(x.propertyId),category:x.category,payee:x.payee,amount:+x.amount||0,note:x.note}));
 if(type==='payments')db.payments.forEach(p=>{const l=find('leases',p.leaseId),u=l&&getLeaseUnit(l);if(!u||!reportPropertyMatch(u.propertyId)||!inRange(p.date))return;rows.push({date:p.date,property:propName(u.propertyId),unit:u.label,resident:tenantName(l.tenantId),month:p.month,amount:+p.amount||0,method:p.method,note:p.note});});
 if(type==='property'||type==='financial')db.properties.filter(p=>reportPropertyMatch(p.id)).forEach(p=>{const units=db.units.filter(u=>u.propertyId===p.id),working=units.filter(u=>u.status!=='offline'),occupied=working.filter(u=>unitState(u)==='Occupied').length,vacant=working.filter(u=>unitState(u)==='Vacant').length, payments=db.payments.filter(pay=>{const l=find('leases',pay.leaseId),u=l&&getLeaseUnit(l);return u?.propertyId===p.id&&inRange(pay.date);}), expenses=db.expenses.filter(x=>x.propertyId===p.id&&inRange(x.date)),paid=payments.reduce((s,x)=>s+(+x.amount||0),0),spent=expenses.reduce((s,x)=>s+(+x.amount||0),0);
 rows.push({property:p.name,address:p.address,city:p.city,region:p.region,type:p.type,units:units.length,occupied,vacant,occupancy:working.length?occupied/working.length*100:0,marketRent:units.reduce((s,x)=>s+(+x.marketRent||0),0),collected:paid,payments:paid,expenses:spent,net:paid-spent,collections:payments.length,transactions:expenses.length,notes:p.notes});});
 if(type==='units')db.units.filter(x=>inProp(x)).forEach(u=>{const l=activeLease(u.id);rows.push({property:propName(u.propertyId),unit:u.label,status:unitState(u),beds:+u.beds||0,baths:+u.baths||0,sqft:+u.sqft||0,marketRent:+u.marketRent||0,resident:l?tenantName(l.tenantId):'',leaseRent:l?+l.rent||0:0,leaseStart:l?.start||'',leaseEnd:l?.end||''});});
 if(type==='residents')db.tenants.forEach(t=>{const ls=db.leases.filter(l=>l.tenantId===t.id).filter(l=>reportPropertyMatch(getLeaseUnit(l)?.propertyId)).sort((a,b)=>b.start.localeCompare(a.start));if(!ls.length&&ui.report.property!=='all')return;const l=ls.find(l=>l.status==='active'&&l.start<=localToday()&&l.end>=localToday())||ls[0];const u=l&&getLeaseUnit(l);rows.push({resident:t.name,preferredName:t.preferredName,property:u?propName(u.propertyId):'',unit:u?.label||'',phone:t.phone,alternatePhone:t.alternatePhone,email:t.email,secondaryEmail:t.secondaryEmail,mailingAddress:t.mailingAddress,language:t.language,contactPreference:t.contactPreference,emergencyName:t.emergencyName,emergencyRelationship:t.emergencyRelationship,emergencyPhone:t.emergencyPhone,emergencyEmail:t.emergencyEmail,occupants:t.occupants,vehicles:t.vehicles,pets:t.pets,notes:t.notes});});
 if(type==='leases')db.leases.forEach(l=>{const u=getLeaseUnit(l);if(!u||!reportPropertyMatch(u.propertyId)||ui.report.from&&l.end<ui.report.from||ui.report.to&&l.start>ui.report.to)return;rows.push({property:propName(u.propertyId),unit:u.label,resident:tenantName(l.tenantId),status:l.status,start:l.start,end:l.end,rent:+l.rent||0,deposit:+l.deposit||0,dueDay:+l.dueDay||1});});
 if(type==='rentroll')reportMonthRange().forEach(ym=>{const end=plusDays(plusMonths(ym,1)+'-01',-1);db.leases.forEach(l=>{const u=getLeaseUnit(l);if(!u||!reportPropertyMatch(u.propertyId)||l.start>end||l.end<ym+'-01')return;const rent=+l.rent||0,paid=paidFor(l.id,ym),balance=Math.max(0,rent-paid);rows.push({month:ym,property:propName(u.propertyId),unit:u.label,resident:tenantName(l.tenantId),rent,paid,balance,status:balance<.005?'Paid':paid>0?'Partial':'Unpaid'});});});
 if(type==='maintenance')db.maintenance.filter(x=>inProp(x)&&inRange(x.dueDate)).forEach(x=>rows.push({property:propName(x.propertyId),unit:find('units',x.unitId)?.label||'Common area',title:x.title,priority:x.priority,status:x.status,assignedTo:x.assignedTo,dueDate:x.dueDate,cost:+x.cost||0,description:x.description}));
 if(type==='tasks')db.tasks.filter(x=>inProp(x)&&inRange(x.dueDate)).forEach(x=>rows.push({property:propName(x.propertyId),title:x.title,dueDate:x.dueDate,status:x.done?'Completed':'Open',notes:x.notes}));
 const col=REPORT_TYPES[type].dateKey;if(col)rows.sort((a,b)=>(b[col]||'').localeCompare(a[col]||''));return rows;}
function reportBuild(){const schema=REPORT_TYPES[ui.report.type],keys=reportCols(),rows=reportData(),columns=keys.map(key=>({key,label:schema.cols[key][0],kind:schema.cols[key][1]||'text'}));const subt=[ui.report.property==='all'?'All properties':propName(ui.report.property),ui.report.from||ui.report.to?`${ui.report.from||'Beginning'} – ${ui.report.to||'No end date'}`:ui.report.type==='rentroll'?fmtMonth(monthNow()):'All available dates'].join(' · ');return {title:ui.report.title.trim()||schema.label,subtitle:subt,columns,rows,currency:db.settings.currency||'USD',totals:ui.report.includeTotals,orientation:ui.report.orientation,disclaimer:schema.hint};}
function reportPreviewCell(value,kind){if(value===undefined||value===null||value==='')return '—';if(kind==='money')return preciseMoney(value);if(kind==='percent')return percent(value);return safe(value);}
function reportPreview(){const data=reportBuild(),cols=data.columns,rows=data.rows;const sums=data.totals?cols.filter(c=>c.kind==='money').map(c=>({label:c.label,value:rows.reduce((n,r)=>n+(+r[c.key]||0),0)})):[];
 return `<div class="report-preview-head"><div><span class="report-overline">REPORT PREVIEW</span><h2>${safe(data.title)}</h2><p>${safe(data.subtitle)}</p></div><span class="report-row-count">${rows.length.toLocaleString()} ${rows.length===1?'record':'records'}</span></div>${cols.length?`<div class="report-preview-table"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${safe(c.label)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.slice(0,100).map(r=>`<tr>${cols.map(c=>`<td>${reportPreviewCell(r[c.key],c.kind)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="report-blank">No records match the selected filters.</td></tr>`}</tbody></table></div>`:'<div class="report-blank">Choose at least one column to preview and export this report.</div>'}${rows.length>100?`<div class="report-preview-meta">Showing the first 100 of ${rows.length.toLocaleString()} rows. Exports include all records.</div>`:''}${sums.length?`<div class="report-totals">${sums.map(s=>`<span>${safe(s.label)} <strong>${preciseMoney(s.value)}</strong></span>`).join('')}</div>`:''}`;}
function renderReports(){const r=ui.report,s=REPORT_TYPES[r.type],checked=reportCols(),rows=reportData(),todayMonth=monthNow();
 return `${pageHeader('OPERATIONS / DOCUMENTS','Report studio','Build a custom report, preview the records, and export the exact columns you need.',`<span class="report-page-count">${db.properties.length} ${db.properties.length===1?'property':'properties'} in workspace</span>`)}
 <div class="report-layout"><section class="panel report-config">
   <div class="report-config-head"><span class="report-step">01</span><div><h2>Build your report</h2><p>Choose a report and customize the details.</p></div></div>
   <div class="report-config-body"><div class="field"><label for="reportType">Report type</label><select id="reportType">${Object.entries(REPORT_TYPES).map(([key,type])=>`<option value="${key}" ${key===r.type?'selected':''}>${safe(type.label)}</option>`).join('')}</select></div><p class="report-type-desc">${safe(s.desc)}</p>
   <div class="report-fields"><div class="field"><label for="reportProperty">Property</label><select id="reportProperty"><option value="all">All properties</option>${db.properties.map(p=>`<option value="${safe(p.id)}" ${r.property===p.id?'selected':''}>${safe(p.name)}</option>`).join('')}</select></div><div class="field"><label for="reportOrientation">Page orientation</label><select id="reportOrientation"><option value="portrait" ${r.orientation==='portrait'?'selected':''}>Portrait</option><option value="landscape" ${r.orientation==='landscape'?'selected':''}>Landscape</option></select></div></div>
   <div class="report-fields"><div class="field"><label for="reportFrom">From ${r.type==='rentroll'?'(month range)':''}</label><input id="reportFrom" type="date" value="${safe(r.from)}"></div><div class="field"><label for="reportTo">To</label><input id="reportTo" type="date" value="${safe(r.to)}"></div></div><div class="report-date-tools"><button class="report-mini-action" data-action="report-current-month" type="button">This month</button><button class="report-mini-action" data-action="report-this-year" type="button">This year</button><button class="report-mini-action" data-action="report-clear-dates" type="button">Clear dates</button></div>
   <div class="field report-title-input"><label for="reportTitle">Report title <span class="report-optional">optional</span></label><input id="reportTitle" maxlength="100" placeholder="${safe(s.label)}" value="${safe(r.title)}"></div>
   <div class="report-columns-head"><div><h3>Select columns</h3><p>Only the selected fields appear in exports.</p></div><div><button class="report-mini-action" data-action="report-all-cols">All</button><button class="report-mini-action" data-action="report-reset-cols">Default</button></div></div><div class="report-column-list">${Object.entries(s.cols).map(([key,c])=>`<label class="report-column ${checked.includes(key)?'is-selected':''}"><input type="checkbox" data-report-col="${safe(key)}" ${checked.includes(key)?'checked':''}><span class="report-col-label">${safe(c[0])}</span><span class="report-col-tick">${icon('check')}</span></label>`).join('')}</div>
   <label class="report-checkline"><input id="reportTotals" type="checkbox" ${r.includeTotals?'checked':''}> Include monetary totals</label></div>
  </section><section class="report-right"><div class="panel report-output"><div class="report-output-title"><div><span class="report-step">02</span><strong>Preview & export</strong></div><span class="report-live">Live preview</span></div><div class="report-preview" id="reportPreview">${reportPreview()}</div></div>
  <div class="report-export-panel panel"><div class="report-export-heading"><strong>Export report</strong><p>All rows · Selected columns · ${r.orientation==='landscape'?'Landscape':'Portrait'}</p></div><div class="report-export-grid"><button class="report-export-btn" data-action="report-pdf" ${!checked.length?'disabled':''} type="button"><span class="report-export-icon pdf">${icon('file-text')}</span><span>PDF<small>Download .pdf</small></span></button><button class="report-export-btn" data-action="report-xlsx" ${!checked.length?'disabled':''} type="button"><span class="report-export-icon xlsx">${icon('file-text')}</span><span>Excel<small>Download .xlsx</small></span></button><button class="report-export-btn" data-action="report-csv" ${!checked.length?'disabled':''} type="button"><span class="report-export-icon csv">${icon('download')}</span><span>CSV<small>Download .csv</small></span></button><button class="report-export-btn" data-action="report-print" ${!checked.length?'disabled':''} type="button"><span class="report-export-icon print">${icon('file-text')}</span><span>Print<small>Browser print view</small></span></button></div></div>
  <div class="report-disclosure">${icon('info')} <span>${safe(s.hint)} Exports contain the current records stored in this workspace. Review reports before sharing.</span></div></section></div>`;}
function reportExport(format){const data=reportBuild();if(!data.columns.length)return toast('Select at least one report column first.','error');try{window.EstateReportExport.export(format,data);if(format==='print')toast('Print layout opened. Use your browser to print or save as PDF.');else toast(format.toUpperCase()+' report created.');}catch(e){console.error(e);toast('Could not export report: '+e.message,'error');}}
function reportUpdatePreview(){const target=el('reportPreview');if(target)target.innerHTML=reportPreview();}

function renderActivity(){const events=filterBySearch(db.activity,x=>x.description+' '+x.detail).slice(0,100);
 return `<div class="panel panel-pad"><div class="panel-heading"><div><h3 class="panel-title">Recent workspace activity</h3><p class="panel-sub">Up to 150 events saved locally or in your cloud workspace</p></div></div>${events.length?events.map(e=>`<div class="timeline-event"><span class="timeline-dot">${icon('activity')}</span><div><div class="timeline-title">${safe(e.description)}</div><div class="timeline-sub">${safe(e.detail||'')} · ${new Date(e.date).toLocaleString('en-US')}</div></div></div>`).join(''):emptyView('No recorded activity','Changes to properties, leases, and payments will appear here.')}</div>`;
}
function renderSettings(){return `<div class="settings-grid"><section class="panel form-panel"><h3>Workspace preferences</h3><form id="settingsForm"><div class="form-grid"><div class="field full"><label for="settingsName">Workspace name</label><input id="settingsName" name="name" maxlength="90" required value="${safe(db.settings.name)}"></div><div class="field full"><label for="currency">Currency</label><select name="currency" id="currency">${[['USD','US Dollar (USD)'],['CAD','Canadian Dollar (CAD)'],['GBP','British Pound (GBP)'],['EUR','Euro (EUR)']].map(([v,t])=>`<option value="${v}" ${db.settings.currency===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="split-actions"><span class="small-muted">Currency changes display symbols; values are not converted.</span><button class="btn btn-primary" type="submit">Save settings</button></div></form></section><section class="panel form-panel"><h3>Data portability</h3><p class="tip" style="margin-top:0">Your data is stored in this browser unless you configure Cloud Sync. Export a backup regularly.</p><div class="split-actions"><button class="btn btn-secondary" data-action="backup">${icon('download')} Export JSON backup</button><button class="btn btn-secondary" data-action="restore">${icon('upload')} Import backup</button></div><input hidden type="file" id="backupFile" accept="application/json,.json"><div class="divider"></div><h3>Reset workspace</h3><p class="small-muted">Permanently clear all records in this browser. Connected cloud data may also be updated. Export a backup first if needed.</p><div class="split-actions"><button class="btn btn-danger" data-action="reset-empty">Clear all records</button></div></section></div>`;}
function renderCloud(){const s=window.CloudSync?.getStatus()||{},ready=!!s.connected;
 return `<div class="settings-grid"><section class="panel form-panel"><h3>Cloud workspace <span class="pill">OPTIONAL</span></h3><p class="tip">To sync between devices, connect your own Supabase project. Data stays private to your authenticated account when you apply the included database access policies.</p><div class="cloud-status"><span class="sync-indicator ${ready?'online':''}"></span><span>${safe(s.message||'Not configured · data stays in this browser')}</span></div><form id="cloudConfigForm"><div class="form-grid"><div class="field full"><label for="cloudUrl">Supabase project URL</label><input id="cloudUrl" name="url" type="url" placeholder="https://yourproject.supabase.co" value="${safe(s.url||'')}" required></div><div class="field full"><label for="cloudKey">Public anon / publishable key</label><input id="cloudKey" name="key" autocomplete="off" value="${safe(s.key||'')}" placeholder="Paste the public key only" required></div></div><div class="split-actions"><span class="small-muted">Never enter a secret/service-role key.</span><button class="btn btn-secondary" type="submit">Save configuration</button></div></form><div class="divider"></div><div class="form-grid"><div class="field full"><label for="cloudEmail">Sign in with an email link</label><input id="cloudEmail" type="email" placeholder="you@example.com" value="${safe(s.email||'')}"></div></div><div class="split-actions"><button class="btn btn-primary" data-action="cloud-login">${icon('lock')} Email sign-in link</button><button class="btn btn-secondary" data-action="cloud-signout">Sign out</button></div><p class="small-muted" style="margin-top:13px">Email links return you to your GitHub Pages URL. Add that URL to the Supabase authentication redirect allowlist.</p></section>
 <section class="panel form-panel"><h3>Synchronization & safety</h3><p class="tip">Cloud synchronization saves workspace records as a single private JSON document per account. This is suitable for one investor or small owner-operated portfolios, not concurrent multi-staff editing.</p><div class="split-actions"><button class="btn btn-secondary" data-action="cloud-download">${icon('download')} Download cloud data</button><button class="btn btn-secondary" data-action="cloud-upload">${icon('upload')} Upload local data</button></div><div class="divider"></div><h3>Getting connected</h3><div class="mini-list"><div class="mini-list-row"><span class="list-rank">1</span><div class="mini-list-body"><div class="mini-list-title">Create a free Supabase project</div><div class="mini-list-sub">You control the database and its billing.</div></div></div><div class="mini-list-row"><span class="list-rank">2</span><div class="mini-list-body"><div class="mini-list-title">Run included supabase.sql</div><div class="mini-list-sub">Enables account-specific row-level security.</div></div></div><div class="mini-list-row"><span class="list-rank">3</span><div class="mini-list-body"><div class="mini-list-title">Set URL & public key, then sign in</div><div class="mini-list-sub">Choose to load cloud data or upload your local workspace.</div></div></div></div><div class="note" style="margin-top:16px">Real rent collection, tenant logins, notifications, document storage, e-signatures and multi-user roles require additional services and are not provided by this app.</div></section></div>`;
}
function field(label,name,value='',options={}){let attrs=`name="${safe(name)}" id="f-${safe(name)}" ${options.required?'required':''} ${options.min!==undefined?`min="${safe(options.min)}"`:''} ${options.max!==undefined?`max="${safe(options.max)}"`:''} ${options.step!==undefined?`step="${safe(options.step)}"`:''}`;
 if(options.type==='textarea')return `<div class="field ${options.full?'full':''}"><label for="f-${name}">${safe(label)}</label><textarea ${attrs} maxlength="3000">${safe(value)}</textarea></div>`;
 if(options.choices)return `<div class="field ${options.full?'full':''}"><label for="f-${name}">${safe(label)}</label><select ${attrs}>${options.placeholder?`<option value="">${safe(options.placeholder)}</option>`:''}${options.choices.map(([k,v])=>`<option value="${safe(k)}" ${String(value)===String(k)?'selected':''}>${safe(v)}</option>`).join('')}</select></div>`;
 return `<div class="field ${options.full?'full':''}"><label for="f-${name}">${safe(label)}</label><input ${attrs} type="${options.type||'text'}" value="${safe(value)}" ${options.type==='number'?'inputmode="decimal"':''} maxlength="${options.type==='text'||options.type==='email'?250:100}"></div>`;
}
const propertyChoices=()=>db.properties.map(p=>[p.id,p.name]);
const unitChoices=()=>db.units.map(u=>[u.id,unitName(u.id)]);
const tenantChoices=()=>db.tenants.map(t=>[t.id,t.name]);
function modalSpec(kind,entity,extra={}){
 const e=entity||{};let title='',subtitle='',form='',footer='Save',warn='';
 if(kind==='property'){
 title=entity?'Edit property':'Add a property';subtitle='Property details and number of rentable units.';
 form=field('Property name','name',e.name||'',{required:true,full:true})+field('Street address','address',e.address||'',{required:true,full:true})+field('City','city',e.city||'',{required:true})+field('State / province','region',e.region||'',{required:true})+field('Property type','type',e.type||'',{choices:['Single family','Duplex','Triplex','Fourplex','Apartment building','Other'].map(x=>[x,x]),placeholder:'Select property type',required:true})+(!entity?field('Create units','count','',{type:'number',min:1,max:500,required:true}):`<div class="field"><label>Units</label><div class="note">Add and edit units separately in the Units section.</div></div>`)+field('Notes','notes',e.notes||'',{type:'textarea',full:true});
 } else if(kind==='unit'){
 if(!db.properties.length)return {error:'Add a property before adding units.'};title=entity?'Edit unit':'Add a unit';subtitle='Set market rent and track unit details.';
 form=field('Property','propertyId',e.propertyId||extra.property||db.properties[0].id,{choices:propertyChoices(),required:true})+field('Unit label','label',e.label||'',{required:true})+field('Bedrooms','beds',e.beds??'',{type:'number',min:0,max:40,step:1})+field('Bathrooms','baths',e.baths??'',{type:'number',min:0,max:20,step:0.5})+field('Square feet','sqft',e.sqft??'',{type:'number',min:0})+field('Market rent ($)','marketRent',e.marketRent??'',{type:'number',min:0,step:0.01})+field('Availability','status',e.status||'available',{choices:[['available','Available (if not leased)'],['offline','Offline / out of service']]});
 } else if(kind==='tenant'){
 title=entity?'Edit resident':'Add a resident';subtitle='Only the name is required. Add more details now or later.';
 form=`<div class="form-section-label">Resident identity & contact</div>`+
 field('Full legal name','name',e.name||'',{required:true,full:true})+field('Preferred name','preferredName',e.preferredName||'')+
 field('Primary phone','phone',e.phone||'',{type:'tel'})+field('Alternate phone','alternatePhone',e.alternatePhone||'',{type:'tel'})+
 field('Email address','email',e.email||'',{type:'email'})+field('Additional email','secondaryEmail',e.secondaryEmail||'',{type:'email'})+
 field('Preferred communication','contactPreference',e.contactPreference||'',{choices:[['','Not specified'],['Phone call','Phone call'],['Text message','Text message'],['Email','Email']],placeholder:'Choose method'})+
 field('Mailing address','mailingAddress',e.mailingAddress||'',{full:true})+
 field('Preferred language','language',e.language||'')+
 `<div class="form-section-label">Emergency contact (optional)</div>`+
 field('Emergency contact name','emergencyName',e.emergencyName||'')+field('Relationship','emergencyRelationship',e.emergencyRelationship||'')+
 field('Emergency phone','emergencyPhone',e.emergencyPhone||'',{type:'tel'})+field('Emergency email','emergencyEmail',e.emergencyEmail||'',{type:'email'})+
 `<div class="form-section-label">Household & property notes (optional)</div>`+
 field('Other authorized occupants','occupants',e.occupants||'',{type:'textarea',full:true})+
 field('Vehicles / parking','vehicles',e.vehicles||'',{full:true})+field('Pets','pets',e.pets||'',{full:true})+
 field('Preferred notice method','noticePreference',e.noticePreference||'',{choices:[['','Not specified'],['Email','Email'],['Mail','Postal mail'],['Hand delivery','Hand delivery'],['Other','Other']],placeholder:'Choose method'})+
 field('Internal notes','notes',e.notes||'',{type:'textarea',full:true});
 warn='Avoid storing Social Security numbers, full ID numbers, payment credentials or other highly sensitive information in this browser-based app.';
 } else if(kind==='communication'){
 if(!db.tenants.length)return {error:'Add a resident before recording contact.'};title=entity?'Edit contact history':'Log a resident contact';subtitle='Record a call, email, text or other interaction. No message is sent.';
 form=field('Resident','tenantId',e.tenantId||extra.tenant||db.tenants[0].id,{choices:tenantChoices(),required:true})+field('Date','date',e.date||localToday(),{type:'date',required:true})+field('Channel','channel',e.channel||'Phone call',{choices:['Phone call','Email','Text message','In person','Other'].map(x=>[x,x])})+field('Subject','subject',e.subject||'',{required:true})+field('Notes','notes',e.notes||'',{type:'textarea',full:true})+field('Follow-up date','followUp',e.followUp||'',{type:'date'});
 } else if(kind==='lease'){
 if(!db.tenants.length||!db.units.length)return {error:'Create a property/unit and a resident before adding a lease.'};title=entity?'Edit lease':'Create a lease';subtitle='Rent is scheduled monthly for each lease that overlaps the month.';
 form=field('Unit','unitId',e.unitId||extra.unit||db.units[0].id,{choices:unitChoices(),required:true})+field('Resident','tenantId',e.tenantId||db.tenants[0].id,{choices:tenantChoices(),required:true})+field('Start date','start',e.start||'',{type:'date',required:true})+field('End date','end',e.end||'',{type:'date',required:true})+field('Monthly rent ($)','rent',e.rent??'',{type:'number',min:0,step:0.01,required:true})+field('Security deposit ($)','deposit',e.deposit??'',{type:'number',min:0,step:0.01})+field('Due on day of month','dueDay',e.dueDay??'',{type:'number',min:1,max:28,step:1})+field('Lease status','status',e.status||'active',{choices:[['active','Active / scheduled'],['ended','Ended']]});
 warn='A lease may cover part of a month but the current rent ledger charges the full monthly amount (no automatic proration).';
 } else if(kind==='payment'){
 if(!db.leases.length)return {error:'Create a lease before recording payments.'};title='Record a payment';subtitle='Manually enter money you have received; no bank transfer occurs.';
 const initial=find('leases',extra.lease)||db.leases.find(l=>l.status==='active')||db.leases[0];const due=+initial.rent-paidFor(initial.id,ui.month);
 form=field('Lease / resident','leaseId',initial.id,{choices:db.leases.map(l=>[l.id,tenantName(l.tenantId)+' · '+unitName(l.unitId)]),required:true,full:true})+field('Rent month','month',ui.month,{type:'month',required:true})+field('Payment date','date',localToday(),{type:'date',required:true})+field('Amount received ($)','amount',Math.max(0,due),{type:'number',min:0.01,step:0.01,required:true})+field('Payment method','method','Bank transfer',{choices:['Bank transfer','Cash','Check','Card','Other'].map(x=>[x,x])})+field('Reference / notes','note','',{type:'textarea',full:true});
 warn='Only actual received payments should be recorded. Payments are not verified with a bank.';
 } else if(kind==='expense'){
 if(!db.properties.length)return {error:'Add a property before recording expenses.'};title=entity?'Edit expense':'Record an expense';subtitle='Track money paid out to operate the property.';
 form=field('Property','propertyId',e.propertyId||db.properties[0].id,{choices:propertyChoices(),required:true})+field('Payment date','date',e.date||localToday(),{type:'date',required:true})+field('Category','category',e.category||'Utilities',{choices:['Mortgage payment','Property tax','Insurance','Utilities','Maintenance','Capital improvement','HOA','Cleaning','Legal & administration','Advertising','Other'].map(x=>[x,x])})+field('Amount paid ($)','amount',e.amount??'',{type:'number',min:0.01,step:0.01,required:true})+field('Payee / vendor','payee',e.payee||'')+field('Notes','note',e.note||'',{type:'textarea',full:true});
 } else if(kind==='maintenance'){
 if(!db.properties.length)return {error:'Add a property before creating work orders.'};title=entity?'Edit work order':'New work order';subtitle='Track repairs from request through completion.';
 form=field('Title','title',e.title||'',{required:true,full:true})+field('Property','propertyId',e.propertyId||db.properties[0].id,{choices:propertyChoices(),required:true})+field('Unit (if applicable)','unitId',e.unitId||'',{choices:[['','Common area / property-wide'],...unitChoices()]})+field('Priority','priority',e.priority||'Normal',{choices:['Low','Normal','High','Urgent'].map(x=>[x,x])})+field('Status','status',e.status||'Open',{choices:['Open','In progress','Completed'].map(x=>[x,x])})+field('Assigned to','assignedTo',e.assignedTo||'')+field('Due date','dueDate',e.dueDate||'',{type:'date'})+field('Actual cost ($)','cost',e.cost??'',{type:'number',min:0,step:0.01})+field('Description','description',e.description||'',{type:'textarea',full:true});
 } else if(kind==='task'){
 if(!db.properties.length)return {error:'Add a property before creating tasks.'};title=entity?'Edit task':'Add a task';subtitle='Create your own operational follow-ups.';
 form=field('Task title','title',e.title||'',{required:true,full:true})+field('Property','propertyId',e.propertyId||db.properties[0].id,{choices:propertyChoices()})+field('Due date','dueDate',e.dueDate||'',{type:'date',required:true})+field('Status','done',e.done?'true':'false',{choices:[['false','Open'],['true','Completed']]})+field('Notes','notes',e.notes||'',{type:'textarea',full:true});
 }else return {error:'Unsupported form'};
 return {title,subtitle,form,footer,warn};
}
function openForm(kind,entityId='',extra={}){const entity=entityId&&kind!=='payment'?find(kind==='property'?'properties':kind==='unit'?'units':kind==='tenant'?'tenants':kind==='lease'?'leases':kind==='task'?'tasks':kind==='expense'?'expenses':kind==='communication'?'communications':'maintenance',entityId):null;
 const spec=modalSpec(kind,entity,extra);if(spec.error){toast(spec.error,'error');return;}
 ui.modal={kind,entityId,extra};el('modalRoot').hidden=false;
 el('modalRoot').innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><form id="entityForm" data-kind="${kind}" data-id="${safe(entityId)}"><div class="modal-head"><div><h2 id="modalTitle">${safe(spec.title)}</h2><p>${safe(spec.subtitle)}</p></div><button class="modal-x" type="button" data-action="close-modal" aria-label="Close">${icon('x')}</button></div><div class="modal-body"><div class="form-grid">${spec.form}</div>${spec.warn?`<div class="note" style="margin-top:18px">${safe(spec.warn)}</div>`:''}</div><div class="modal-footer"><button class="btn btn-secondary" data-action="close-modal" type="button">Cancel</button><button class="btn btn-primary" type="submit">${entity?'Save changes':kind==='payment'?'Record payment':'Create'}</button></div></form></div>`;
 window.EstateSelects?.enhance(el('modalRoot'));
 el('modalRoot').querySelector('input:not([type=hidden]),textarea,.ed-choice-button')?.focus();
}
function openInfo(title,body){ui.modal={kind:'info'};el('modalRoot').hidden=false;el('modalRoot').innerHTML=`<div class="modal-card" role="dialog" aria-modal="true"><div class="modal-head"><h2>${safe(title)}</h2><button class="modal-x" type="button" data-action="close-modal" aria-label="Close">${icon('x')}</button></div><div class="modal-body">${body}</div><div class="modal-footer"><button class="btn btn-primary" type="button" data-action="close-modal">Close</button></div></div>`;window.EstateSelects?.enhance(el('modalRoot'));}
function closeModal(){window.EstateSelects?.close();ui.modal=null;el('modalRoot').hidden=true;el('modalRoot').innerHTML='';}
function handleEntitySubmit(form){const kind=form.dataset.kind,entityId=form.dataset.id,raw=Object.fromEntries(new FormData(form).entries()),v=Object.fromEntries(Object.entries(raw).map(([k,val])=>[k,typeof val==='string'?val.trim():val]));
 const n=(key)=>Number(v[key]||0),err=(message)=>{toast(message,'error');return false;};
 if(kind==='property'){
 if(!v.name||!v.address||!v.city||!v.region||!v.type)return err('Complete all required property details.');
 if(entityId){const p=find('properties',entityId);Object.assign(p,{name:v.name,address:v.address,city:v.city,region:v.region,type:v.type,notes:v.notes});}
 else {const count=n('count');if(!Number.isInteger(count)||count<1||count>500)return err('Choose between 1 and 500 units.');const propId=id();db.properties.push({id:propId,name:v.name,address:v.address,city:v.city,region:v.region,type:v.type,notes:v.notes});for(let i=1;i<=count;i++)db.units.push({id:id(),propertyId:propId,label:`Unit ${i}`,beds:null,baths:null,sqft:null,marketRent:null,status:'available'});}
 }else if(kind==='unit'){
 if(!v.propertyId||!v.label)return err('Property and unit label are required.');
 if(db.units.some(x=>x.propertyId===v.propertyId&&x.label.toLowerCase()===v.label.toLowerCase()&&x.id!==entityId))return err('A unit with that label already exists at this property.');
 const data={propertyId:v.propertyId,label:v.label,beds:v.beds===''?null:n('beds'),baths:v.baths===''?null:n('baths'),sqft:v.sqft===''?null:n('sqft'),marketRent:v.marketRent===''?null:n('marketRent'),status:v.status};
 if(entityId){const u=find('units',entityId);if(db.leases.some(l=>l.unitId===entityId)&&u.propertyId!==v.propertyId)return err('You cannot move a unit with lease history to another property.');Object.assign(u,data);}else db.units.push({id:id(),...data});
 }else if(kind==='tenant'){
 if(!v.name)return err('Resident name is required.');const data={name:v.name,preferredName:v.preferredName,email:v.email,secondaryEmail:v.secondaryEmail,phone:v.phone,alternatePhone:v.alternatePhone,mailingAddress:v.mailingAddress,language:v.language,contactPreference:v.contactPreference,emergencyName:v.emergencyName,emergencyRelationship:v.emergencyRelationship,emergencyPhone:v.emergencyPhone,emergencyEmail:v.emergencyEmail,occupants:v.occupants,vehicles:v.vehicles,pets:v.pets,noticePreference:v.noticePreference,notes:v.notes};if(entityId)Object.assign(find('tenants',entityId),data);else db.tenants.push({id:id(),...data});
 }else if(kind==='communication'){
 if(!v.tenantId||!v.date||!v.subject)return err('Resident, date and subject are required.');
 const data={tenantId:v.tenantId,date:v.date,channel:v.channel,subject:v.subject,notes:v.notes,followUp:v.followUp};
 if(entityId)Object.assign(find('communications',entityId),data);else db.communications.push({id:id(),...data});
 }else if(kind==='lease'){
 if(!v.unitId||!v.tenantId||!v.start||!v.end)return err('Complete unit, resident, and lease dates.');
 if(v.start>v.end)return err('Lease end date cannot be earlier than start date.');
 if(v.status==='ended' && v.end>localToday())v.end=localToday()<v.start?v.start:localToday();
 if(n('rent')<0||n('deposit')<0)return err('Rent and deposit cannot be negative.');
 if(db.leases.some(l=>l.id!==entityId&&l.unitId===v.unitId&&l.status==='active'&&v.status==='active'&&isOverlap(l,v.start,v.end)))return err('That unit already has an overlapping active lease.');
 if(find('units',v.unitId)?.status==='offline'&&v.status==='active')return err('The unit is marked offline. Update its availability before leasing.');
 const data={unitId:v.unitId,tenantId:v.tenantId,start:v.start,end:v.end,rent:n('rent'),deposit:n('deposit'),dueDay:Math.max(1,Math.min(28,n('dueDay')||1)),status:v.status};
 if(entityId)Object.assign(find('leases',entityId),data);else db.leases.push({id:id(),...data});
 }else if(kind==='payment'){
 if(!v.leaseId||!v.month||!v.date||!(n('amount')>0))return err('Choose a lease and enter a positive amount.');
 if(!/^\d{4}-\d{2}$/.test(v.month))return err('Choose a valid rent month.');
 db.payments.push({id:id(),leaseId:v.leaseId,month:v.month,date:v.date,amount:Math.round(n('amount')*100)/100,method:v.method,note:v.note});ui.month=v.month;
 }else if(kind==='expense'){
 if(!v.propertyId||!v.date||!(n('amount')>0))return err('Complete the property, date, and positive expense amount.');
 const data={propertyId:v.propertyId,date:v.date,category:v.category,amount:Math.round(n('amount')*100)/100,payee:v.payee,note:v.note};
 if(entityId)Object.assign(find('expenses',entityId),data);else db.expenses.push({id:id(),...data});
 }else if(kind==='maintenance'){
 if(!v.title||!v.propertyId)return err('Work order title and property are required.');
 if(v.unitId&&find('units',v.unitId)?.propertyId!==v.propertyId)return err('The selected unit belongs to a different property.');
 const data={title:v.title,propertyId:v.propertyId,unitId:v.unitId||'',priority:v.priority,status:v.status,assignedTo:v.assignedTo,cost:n('cost'),dueDate:v.dueDate,description:v.description};
 if(entityId)Object.assign(find('maintenance',entityId),data);else db.maintenance.push({id:id(),createdAt:localToday(),...data});
 }else if(kind==='task'){
 if(!v.title||!v.propertyId||!v.dueDate)return err('Title, property, and due date are required.');
 const data={title:v.title,propertyId:v.propertyId,dueDate:v.dueDate,notes:v.notes,done:v.done==='true'};
 if(entityId)Object.assign(find('tasks',entityId),data);else db.tasks.push({id:id(),...data});
 }
 const label={property:'Property',unit:'Unit',tenant:'Resident',lease:'Lease',payment:'Payment',maintenance:'Work order',expense:'Expense',task:'Task',communication:'Resident contact'}[kind]||'Record';closeModal();record(`${label} ${entityId?'updated':kind==='payment'?'recorded':'created'}`,v.name||v.title||v.label||v.amount||'');toast(`${label} ${entityId?'updated':'saved'}`);return true;
}
function handleDelete(kind,entityId){const map={property:'properties',unit:'units',tenant:'tenants',lease:'leases',payment:'payments',expense:'expenses',maintenance:'maintenance',task:'tasks',communication:'communications'},key=map[kind],entry=key&&find(key,entityId);if(!entry)return;
 if(kind==='property'){
 const units=db.units.filter(u=>u.propertyId===entityId),unitIds=new Set(units.map(x=>x.id));if(db.leases.some(l=>unitIds.has(l.unitId)))return toast('Cannot delete this property while its units have lease history.','error');
 if(!confirm(`Delete ${entry.name} and its ${units.length} units? Any related tasks and work orders will also be deleted.`))return;
 db.units=db.units.filter(u=>!unitIds.has(u.id));db.tasks=db.tasks.filter(t=>t.propertyId!==entityId);db.maintenance=db.maintenance.filter(t=>t.propertyId!==entityId);db.expenses=db.expenses.filter(t=>t.propertyId!==entityId);
 }else if(kind==='unit'){
 if(db.leases.some(l=>l.unitId===entityId))return toast('Cannot delete a unit with lease history. Mark it offline instead.','error');
 if(!confirm(`Delete ${entry.label}?`))return;db.maintenance=db.maintenance.filter(w=>w.unitId!==entityId);
 }else if(kind==='tenant'){
 if(db.leases.some(l=>l.tenantId===entityId))return toast('Cannot delete a resident with lease history.','error');if(!confirm(`Delete ${entry.name} and any contact history?`))return;db.communications=db.communications.filter(c=>c.tenantId!==entityId);
 }else if(kind==='lease'){
 if(db.payments.some(p=>p.leaseId===entityId))return toast('Cannot delete a lease with recorded payments.','error');if(!confirm('Delete this lease?'))return;
 }else {if(!confirm(`Delete this ${kind}?`))return;}
 db[key]=db[key].filter(x=>x.id!==entityId);if(kind==='property')ui.property='all';record(`${kind[0].toUpperCase()+kind.slice(1)} deleted`,entry.name||entry.label||entry.title||'');if(kind==='payment'&&ui.modal?.kind==='info')showPaymentHistory(entry.leaseId);toast('Record deleted');
}
function showPaymentHistory(leaseId){const l=find('leases',leaseId);if(!l)return;const ps=db.payments.filter(x=>x.leaseId===leaseId).sort((a,b)=>b.date.localeCompare(a.date));const body=`<p class="small-muted">${safe(tenantName(l.tenantId))} · ${safe(unitName(l.unitId))}</p>${ps.length?shellTable(['Paid on','Rent month','Amount','Method',''],ps.map(p=>`<tr><td>${fmtDate(p.date)}</td><td>${safe(p.month)}</td><td class="money-cell">${preciseMoney(p.amount)}</td><td>${safe(p.method)}</td><td><button class="table-action" data-action="delete" data-kind="payment" data-id="${p.id}">Delete</button></td></tr>`).join('')):'<div class="small-muted">No recorded payments.</div>'}`;
 openInfo('Payment history',body);
}
function downloadBlob(filename,content,mime){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:mime}));a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function csvCell(s){const v=String(s??'');return `"${(/^[=+@\-\t\r]/.test(v)?"'":'')+v.replace(/"/g,'""')}"`;}
function exportRent(){const head=['Month','Property','Unit','Resident','Due','Paid','Balance'];const rows=ledger(ui.month).map(l=>[ui.month,propName(getLeaseUnit(l)?.propertyId),getLeaseUnit(l)?.label||'',tenantName(l.tenantId),l.due,l.paid,l.remaining]);downloadBlob(`estatedock-rent-${ui.month}.csv`,[head,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Rent CSV downloaded');}
function exportBackup(){downloadBlob(`estatedock-backup-${localToday()}.json`,JSON.stringify(db,null,2),'application/json');toast('Workspace backup downloaded');}
function loadBackup(file){if(!file)return;file.text().then(text=>{let next;try{next=JSON.parse(text);}catch(e){return toast('Invalid JSON file.','error');}if(!validDb(next))return toast('This is not a compatible EstateDock backup.','error');if(!confirm('Replace all local workspace data with this backup? Export current data first if needed.'))return;db=normalizeDb(next);ui.property='all';ui.selectedDeals=[];ui.editingDealId=null;save('Workspace backup restored',file.name);toast('Backup restored');}).catch(()=>toast('Could not read backup','error'));}
function onAction(btn){const act=btn.dataset.action,kind=btn.dataset.kind,entityId=btn.dataset.id;
 if(act==='resident-profile')return showResidentProfile(entityId);
 if(act==='report-pdf'||act==='report-xlsx'||act==='report-csv'||act==='report-print')return reportExport(act.slice(7));
 if(act==='report-all-cols'){ui.report.columnsByType[ui.report.type]=Object.keys(REPORT_TYPES[ui.report.type].cols);return render();}
 if(act==='report-reset-cols'){ui.report.columnsByType[ui.report.type]=[...REPORT_TYPES[ui.report.type].defaultCols];return render();}
 if(act==='report-clear-dates'){ui.report.from='';ui.report.to='';return render();}
 if(act==='report-current-month'||act==='report-this-year'){const ym=monthNow();ui.report.from=act==='report-current-month'?ym+'-01':ym.slice(0,4)+'-01-01';ui.report.to=act==='report-current-month'?plusDays(plusMonths(ym,1)+'-01',-1):ym.slice(0,4)+'-12-31';return render();}
 if(act==='analyzer-new'){ui.editingDealId=null;ui.analyzer=blankAnalyzer();ui.analyzerMode='quick';render();return;}
 if(act==='analyzer-quick'||act==='analyzer-advanced'||act==='analyzer-compare'){ui.analyzerMode=act.slice('analyzer-'.length);render();return;}
 if(act==='deal-clear'){ui.analyzer=blankAnalyzer();ui.editingDealId=null;render();return;}
 if(act==='deal-save'){if(!dealReady(ui.analyzer))return toast('Enter valid purchase price, units, rent, down payment and interest rate first.','error');const a={...ui.analyzer};const dealName=String(a.dealName||'').trim()||`${a.units}-unit deal · ${money(a.price)}`;delete a.dealName;let dealId=ui.editingDealId;const existing=db.deals.find(d=>d.id===dealId);if(existing){Object.assign(existing,{name:dealName,input:a,updatedAt:new Date().toISOString()});}else{dealId=id();db.deals.push({id:dealId,name:dealName,input:a,createdAt:new Date().toISOString()});}ui.selectedDeals=[...new Set([...ui.selectedDeals,dealId])].slice(-3);ui.editingDealId=dealId;record(existing?'Saved deal updated':'Deal saved for comparison',dealName);toast(existing?'Saved deal updated':'Deal saved — open Compare deals to review it.');return;}
 if(act==='deal-delete'){const d=db.deals.find(x=>x.id===entityId);if(!d)return;if(!confirm(`Remove ${d.name} from your saved comparisons?`))return;db.deals=db.deals.filter(x=>x.id!==entityId);ui.selectedDeals=ui.selectedDeals.filter(x=>x!==entityId);record('Saved deal removed',d.name);return;}
 if(act==='deal-load'){const d=db.deals.find(x=>x.id===entityId);if(!d)return;ui.analyzer={...blankAnalyzer(),...d.input,dealName:d.name};ui.editingDealId=d.id;ui.analyzerMode='advanced';render();return;}
 if(act==='open-unit-board'){ui.unitView='board';return setRoute('units');}
 if(act==='unit-board'||act==='unit-list'){ui.unitView=act==='unit-board'?'board':'list';render();return;}
 if(act==='add')return openForm(kind,'',{unit:btn.dataset.unit,lease:btn.dataset.lease,tenant:btn.dataset.tenant});
 if(act==='edit')return openForm(kind,entityId);
 if(act==='delete'){const residentId=kind==='communication'?find('communications',entityId)?.tenantId:null;handleDelete(kind,entityId);if(residentId&&find('tenants',residentId))showResidentProfile(residentId);return;}
 if(act==='close-modal')return closeModal();
 if(act==='view-property'){ui.property=entityId;return setRoute('units');}
 if(act==='month-prev'||act==='month-next'){ui.month=plusMonths(ui.month,act==='month-next'?1:-1);return render();}
 if(act==='calendar-prev'||act==='calendar-next'){ui.calendarMonth=plusMonths(ui.calendarMonth,act==='calendar-next'?1:-1);return render();}
 if(act==='export-rent')return exportRent();
 if(act==='export-expenses')return exportExpenses();
 if(act==='payment-history')return showPaymentHistory(entityId);
 if(act==='complete-work'){const w=find('maintenance',entityId);if(w){w.status='Completed';record('Work order completed',w.title);toast('Work order marked complete');}return;}
 if(act==='toggle-task'){const t=find('tasks',entityId);if(t){t.done=!t.done;record('Task '+(t.done?'completed':'reopened'),t.title);}return;}
 if(act==='end-lease'){const l=find('leases',entityId);if(!l)return;if(l.status==='ended')return toast('Lease is already ended.');if(!confirm(`End the lease for ${tenantName(l.tenantId)}? Rent history will be preserved.`))return;l.status='ended';if(l.end>localToday())l.end=localToday()<l.start?l.start:localToday();record('Lease ended',tenantName(l.tenantId));toast('Lease ended');return;}
 if(act==='backup')return exportBackup();
 if(act==='restore'){el('backupFile')?.click();return;}
 if(act==='reset-empty'){if(!confirm('Permanently erase all workspace records in this browser? Export a backup first if needed.'))return;db=empty();ui.property='all';ui.analyzer=blankAnalyzer();ui.selectedDeals=[];ui.editingDealId=null;ui.analyzerMode='quick';try{localStorage.setItem(STORAGE,JSON.stringify(db));}catch(e){}render();window.CloudSync?.scheduleSave(db);toast('Workspace cleared');return;}
 if(act==='cloud-login'){const email=el('cloudEmail')?.value.trim();window.CloudSync?.sendLink(email).then(()=>{render();toast('Check your email for the sign-in link');}).catch(e=>toast(e.message,'error'));return;}
 if(act==='cloud-signout'){window.CloudSync?.signOut().then(()=>{render();toast('Signed out');}).catch(e=>toast(e.message,'error'));return;}
 if(act==='cloud-download'){if(!confirm('Download cloud records and replace your local workspace? Export a backup first if needed.'))return;window.CloudSync?.download().then(ok=>{if(ok)toast('Cloud data loaded');}).catch(e=>toast(e.message,'error'));return;}
 if(act==='cloud-upload'){if(!confirm('Overwrite the cloud workspace with current local records? Other devices may have newer changes.'))return;window.CloudSync?.upload(JSON.parse(JSON.stringify(db))).then(()=>{render();toast('Workspace uploaded');}).catch(e=>toast(e.message,'error'));return;}
}
function help(){openInfo('About EstateDock',`<div class="alert info">EstateDock is an independent-owner property operations MVP, designed with a hotel front-desk-inspired workflow.</div><div class="mini-list"><div class="mini-list-row"><span class="mini-icon">${icon('check')}</span><div class="mini-list-body"><div class="mini-list-title">What works</div><div class="mini-list-sub">Properties and units, resident profiles and contact history, leases, rent balances, manually logged payments, operating expenses, tasks, maintenance, configurable reports with PDF/Excel/CSV/print exports, backup import/export, and an optional cloud workspace.</div></div></div><div class="mini-list-row"><span class="mini-icon">${icon('alert-circle')}</span><div class="mini-list-body"><div class="mini-list-title">What isn't included</div><div class="mini-list-sub">Bank payments, tenant portals, automatic rent reminders, e-signatures, document management, accounting integrations, regulatory notices, secure role-based staff access, and audit-grade accounting.</div></div></div><div class="mini-list-row"><span class="mini-icon">${icon('shield-check')}</span><div class="mini-list-body"><div class="mini-list-title">Data & privacy</div><div class="mini-list-sub">Default storage is local to this browser. Enable Supabase Cloud Sync and row-level security to privately synchronize between devices. Do not rely solely on browser storage for critical records.</div></div></div></div>`);}
function quickNew(){openInfo('Create new',`<p class="small-muted">Choose what to add to your workspace.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:18px">${[['property','Property'],['unit','Unit'],['tenant','Resident'],['lease','Lease'],['payment','Payment'],['expense','Expense'],['maintenance','Work order'],['task','Task']].map(([kind,label])=>`<button class="btn btn-secondary" data-action="add" data-kind="${kind}">${icon('plus')} ${label}</button>`).join('')}</div>`);}
function handleAnalyzerInput(target){if(ui.route!=='more'||ui.moreTab!=='analyzer')return;const form=target.closest('#analyzerInputs');if(!form||!target.name)return;
 if(target.type==='checkbox')ui.analyzer[target.name]=target.checked;
 else if(['loanType','dealName'].includes(target.name))ui.analyzer[target.name]=target.value;
 else ui.analyzer[target.name]=target.value===''?'':Number(target.value);
 if(target.name==='units'&&ui.analyzer.occupied!=='')ui.analyzer.occupied=Math.min(ui.analyzer.units,ui.analyzer.occupied);
 if(target.name==='loanType'){render();return;}
 updateCalc();}
function handleChange(e){const t=e.target;
 if(t.id==='reportType'){ui.report.type=t.value;ui.report.title='';return render();}
 if(t.id==='reportProperty'){ui.report.property=t.value;return render();}
 if(t.id==='reportOrientation'){ui.report.orientation=t.value;return render();}
 if(t.id==='reportFrom'||t.id==='reportTo'){ui.report[t.id==='reportFrom'?'from':'to']=t.value;if(ui.report.from&&ui.report.to&&ui.report.from>ui.report.to){toast('Start date must be on or before end date.','error');return;}return render();}
 if(t.id==='reportTotals'){ui.report.includeTotals=t.checked;return reportUpdatePreview();}
 if(t.matches('[data-report-col]')){const key=t.dataset.reportCol,cols=reportCols();ui.report.columnsByType[ui.report.type]=t.checked?[...cols,key]:cols.filter(x=>x!==key);return render();}
if(t.id==='propertyFilter'){ui.property=t.value;render();return;}if(t.id==='rentStatusFilter'){ui.rentFilter=t.value;render();return;}if(t.id==='maintenanceFilter'){ui.maintenanceFilter=t.value;render();return;}if(t.id==='backupFile'){loadBackup(t.files[0]);return;}if(t.matches('.compare-check')){if(t.checked){if(ui.selectedDeals.length>=3){t.checked=false;toast('Compare up to three deals at once.','error');return;}ui.selectedDeals.push(t.dataset.id);}else ui.selectedDeals=ui.selectedDeals.filter(x=>x!==t.dataset.id);render();return;}if(t.closest('#analyzerInputs'))handleAnalyzerInput(t);}
function handleSubmit(e){e.preventDefault();const f=e.target;
 if(f.id==='entityForm')return handleEntitySubmit(f);
 if(f.id==='settingsForm'){const data=Object.fromEntries(new FormData(f).entries());db.settings.name=String(data.name).trim().slice(0,90)||'My Portfolio';db.settings.currency=data.currency||'USD';record('Workspace settings updated');toast('Settings saved');return;}
 if(f.id==='cloudConfigForm'){const v=Object.fromEntries(new FormData(f).entries());const email=el('cloudEmail')?.value.trim()||'';window.CloudSync?.configure(v.url,v.key,email).then(()=>{render();toast('Cloud configuration saved');}).catch(err=>toast(err.message,'error'));}
}
function cloudInit(){window.CloudSync?.init({getLocal:()=>db,onRemote:(remote,force=false)=>{
 if(!validDb(remote)){toast('Cloud data is not a compatible EstateDock workspace.','error');return false;}
 if(JSON.stringify(remote)===JSON.stringify(db))return true;
 const shouldLoad=force||confirm('A saved cloud workspace was found. Load the cloud copy on this device? Cancel to keep local records, then use Cloud Sync to choose which copy to keep.');
 if(shouldLoad){db=normalizeDb(remote);ui.property='all';ui.selectedDeals=[];ui.editingDealId=null;localStorage.setItem(STORAGE,JSON.stringify(db));render();toast('Cloud workspace loaded');return true;}return false;
 },onStatus:status=>{el('syncLabel').textContent=status.connected?'Cloud synced':(status.message?.startsWith('Cloud error')?'Cloud sync error':'Stored on this device');el('syncIndicator').className='sync-indicator '+(status.connected?'online':status.message?.startsWith('Cloud error')?'error':'');if(ui.route==='more'&&ui.moreTab==='cloud'){const target=el('mainContent');if(target&&!document.activeElement?.closest('form'))render();}},onError:msg=>toast(msg,'error')});}
 document.addEventListener('click',e=>{
  if(e.target===el('modalRoot')){closeModal();return;}
  const b=e.target.closest('[data-route],[data-more],[data-action]');if(!b)return;
  if(b.dataset.route){e.preventDefault();return setRoute(b.dataset.route);}
  if(b.dataset.more!==undefined){e.preventDefault();return setRoute('more',b.dataset.more);}
  if(b.dataset.action){e.preventDefault();return onAction(b);}
 });
 document.addEventListener('submit',handleSubmit);
 document.addEventListener('change',handleChange);
 document.addEventListener('input',e=>{if(e.target.id==='reportTitle'){ui.report.title=e.target.value;reportUpdatePreview();return;}if(e.target.closest('#analyzerInputs')&&e.target.type!=='checkbox'&&e.target.tagName!=='SELECT')handleAnalyzerInput(e.target);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal)closeModal();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();el('globalSearch').focus();}});
 el('globalSearch').addEventListener('input',e=>{ui.search=e.target.value;render();});
 el('newButton').addEventListener('click',quickNew);
 el('helpButton').addEventListener('click',help);
 el('menuToggle').addEventListener('click',()=>{el('sidebar').classList.add('open');el('sidebarBackdrop').hidden=false;});
 el('sidebarBackdrop').addEventListener('click',closeMenu);
 el('workspaceBtn').addEventListener('click',()=>setRoute('more','settings'));
 window.addEventListener('hashchange',()=>{const [route,tab]=location.hash.slice(1).split('/');if(route!==ui.route||tab!==ui.moreTab)setRoute(route,tab||'');});
 try{if(!localStorage.getItem(STORAGE))localStorage.setItem(STORAGE,JSON.stringify(db));}catch(e){}
 hydrateIcons(document);render();cloudInit();
 if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost')) navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
